"use client";

import { useEffect, useMemo, useState } from "react";
import { applications as seedApplications, tasks as seedTasks, submissions as seedSubmissions, rewards as seedRewards, streakRequests as seedStreakRequests, paymentForms as seedPaymentForms, creatorProfiles as seedCreatorProfiles, leaderboard, fmtIdr, fmtNum, type Product, type Application, type Task, type Submission, type Reward, type AppExpansionRequest, type StreakRequest, type PaymentForm, type CreatorProfile } from "./platform-data";
import { citiesForProvince, indonesiaProvinces } from "./indonesia-locations";
import { countryCallingCodes } from "./country-codes";
import { PortalLanguageProvider, PortalLanguageSwitcher, usePortalLanguage } from "./portal-language";
import { supabase } from "./supabase-browser";

type Space = "team" | "creator" | "public";
type Modal = "application" | "auth" | "task" | "submission" | "review" | "new-apps" | "task-preview" | "edit-task" | "team-profile" | null;
type Account = {id:string;email:string;role:"creator"|"team";applicationStatus:"in_review"|"accepted"|"declined"};

const teamNav = [["Overview","⌂"],["Applications","◎"],["Creators","♙"],["Campaigns","□"],["Submissions","↗"],["Rewards","◇"],["Payment Forms","$"]];
const creatorNav = [["Home","⌂"],["Campaigns","□"],["Submissions","↗"],["Rewards","◇"],["Leaderboard","♜"],["Profile","○"]];
const productClass = (p:string) => `product product-${p.toLowerCase()}`;
const badgeClass = (s:string) => `badge badge-${s.toLowerCase().replaceAll(" ","-").replaceAll("/","")}`;
const applicationStatus = (status:string) => status==="Accepted"||status==="Declined"?status:"In review";
const storedApplication=(row:{id:string;status:string;decline_reason?:string|null;submitted_at:string;application_data:Application}):Application=>({...row.application_data,id:row.id,status:row.status==="accepted"?"Accepted":row.status==="declined"?"Declined":"In review",declineReason:row.decline_reason||"",submitted:row.submitted_at});
const storedCreatorSettings=(row:{creator_id:string;display_name:string;contact_email:string;niches:string;tiktok_url?:string|null;instagram_url?:string|null;threads_url?:string|null;whatsapp?:string|null;avatar_key?:string|null;avatar_name?:string|null;updated_at?:string|null}):CreatorProfile=>({id:row.creator_id,creator:currentCreator,displayName:row.display_name,contactEmail:row.contact_email,niches:row.niches,tiktokUrl:row.tiktok_url||"",instagramUrl:row.instagram_url||"",threadsUrl:row.threads_url||"",whatsapp:row.whatsapp||"",avatarKey:row.avatar_key||"",avatarName:row.avatar_name||"",updatedAt:row.updated_at||""});
type StoredCampaign={id:string;title:string;product:Product;reference_link?:string|null;tutorial_link?:string|null;deadline:string;status:string;task_data?:Partial<Task>|null};
const storedCampaign=(row:StoredCampaign):Task=>{const details=row.task_data||{};return {...details,id:row.id,title:row.title,product:row.product,referenceLink:row.reference_link||details.referenceLink||"",tutorialLink:row.tutorial_link||details.tutorialLink||"",deadline:row.deadline.slice(0,10),platform:details.platform||"TikTok · Instagram · Threads",startsAt:details.startsAt||row.deadline.slice(0,10),joined:details.joined||0,budget:0,status:row.status==="closed"?"Closed":row.status==="draft"?"Draft":"Active",progress:details.progress||0,cover:details.cover|| (row.product==="Meitu"?"peach":row.product==="Wink"?"violet":"blue"),niches:details.niches||"Beauty",brief:details.brief||""};};
const kolCategories=["Beauty","Fashion","Food F&B","Travel & Nature","Lifestyle","Comedy & Skits","JJ & Trends","Commentary / Storytelling","Family / Couple","Education / Motivational","Tech & Gadgets","Gaming","Kpop / Dance / Concert","Editing / Photography"];
const normalizedCategory=(category:string)=>{const value=category.trim();const lower=value.toLowerCase();if(lower.includes("beauty"))return "Beauty";if(lower.includes("fashion"))return "Fashion";if(lower==="food"||lower.includes("f&b"))return "Food F&B";if(lower.includes("travel"))return "Travel & Nature";if(lower.includes("lifestyle"))return "Lifestyle";if(lower.includes("humor")||lower.includes("comedy")||lower.includes("skit"))return "Comedy & Skits";if(lower.includes("jj")||lower.includes("trend"))return "JJ & Trends";if(lower.includes("commentary")||lower.includes("storytelling"))return "Commentary / Storytelling";if(lower.includes("family")||lower.includes("couple"))return "Family / Couple";if(lower.includes("education")||lower.includes("motivational"))return "Education / Motivational";if(lower.includes("tech")||lower.includes("gadget"))return "Tech & Gadgets";if(lower.includes("gaming"))return "Gaming";if(lower.includes("k-pop")||lower.includes("kpop")||lower.includes("dance")||lower.includes("concert"))return "Kpop / Dance / Concert";if(lower.includes("edit")||lower.includes("photo"))return "Editing / Photography";return kolCategories.includes(value)?value:"Lifestyle"};
const categoryIcons:Record<string,string>={"Beauty":"✦","Fashion":"◇","Food F&B":"♨","Travel & Nature":"↗","Lifestyle":"☼","Comedy & Skits":"☺","JJ & Trends":"♫","Commentary / Storytelling":"✎","Family / Couple":"♥","Education / Motivational":"★","Tech & Gadgets":"⌁","Gaming":"◉","Kpop / Dance / Concert":"♪","Editing / Photography":"▣"};
const categoryIcon=(category:string)=>categoryIcons[normalizedCategory(category)]||"✦";
const categoryList=(value:string)=>value.split(",").map(normalizedCategory).filter(Boolean);
const taskNiches=(task:Task)=>categoryList(task.niches||({Meitu:"Beauty,Lifestyle,Fashion",BeautyCam:"Beauty,Fashion,Family / Couple",Wink:"Editing / Photography,JJ & Trends,Kpop / Dance / Concert"}[task.product]));
const currentCreator="Salsa Nabila";
const rewardTiers=[
  {views:0,label:"<10.000 Views",reward:"Submit tanpa Reward",amount:0},
  {views:10000,label:"10.000 Views",reward:"VIP 1 Bulan",amount:0},
  {views:100000,label:"100.000 Views",reward:"Rp500.000",amount:500000},
  {views:250000,label:"250.000 Views",reward:"Rp1.250.000",amount:1250000},
  {views:500000,label:"500.000 Views",reward:"Rp2.500.000",amount:2500000},
  {views:1000000,label:"1 Juta Views",reward:"Rp5.000.000",amount:5000000},
];
const rewardTierForViews=(views:number)=>[...rewardTiers].reverse().find(tier=>views>=tier.views);
const normalizeSubmissionStatus=(status:string)=>status==="Draft"?"Draft":status==="Qualified"||status==="Approved"?"Qualified":status==="Not Qualified"||status==="Revision requested"?"Not Qualified":"In review";
const normalizeRewardStatus=(reward:Reward)=>{const current=reward.status;const normalized=current==="Fully Paid"||current==="In Payment"||current==="Pay Fail"||current==="Please Fill In Payment Form"?current:current==="On Hold"?"Pay Fail":reward.paidAt?"Fully Paid":reward.paymentFormChecked?"In Payment":"Please Fill In Payment Form";return {...reward,status:normalized}};
const displayDate=(value?:string)=>{if(!value)return "—";const date=new Date(value);return Number.isNaN(date.getTime())?value:new Intl.DateTimeFormat("en-GB",{day:"numeric",month:"short",year:"numeric"}).format(date)};
const submittedWithinSevenDays=(publishedAt?:string,submittedAt?:string)=>{if(!publishedAt||!submittedAt)return true;const published=new Date(`${publishedAt}T00:00:00`).getTime();const submitted=new Date(submittedAt).getTime();return submitted-published<=7*24*60*60*1000};
const taskStatusFor=(task:Task):"Ongoing"|"Expired"=>{const deadline=new Date(`${task.deadline}T23:59:59`);return Number.isNaN(deadline.getTime())||deadline.getTime()>=Date.now()?"Ongoing":"Expired"};
const followerCount=(application:Application)=>{const value=application.followers.trim().toUpperCase().replaceAll(",","");const parsed=Number.parseFloat(value);if(Number.isNaN(parsed))return 0;return value.endsWith("M")?parsed*1000000:value.endsWith("K")?parsed*1000:parsed};
const engagementTotalFor=(submission:Submission)=>submission.totalEngagement||Math.round(submission.aiViews*(submission.engagementRate||0)/100);
const engagementRateFor=(submission:Submission)=>submission.analyticsStatus==="Manual override"?(submission.engagementRate||0):submission.aiViews>0?(engagementTotalFor(submission)/submission.aiViews)*100:(submission.engagementRate||0);
const whatsappCountryCodes=countryCallingCodes;
const normalizeWhatsApp=(countryCode:string,localNumber:string)=>countryCode.replace(/\D/g,"")+localNumber.replace(/\D/g,"").replace(/^0+/,"");
const splitWhatsApp=(value?:string)=>{const digits=(value||"").replace(/\D/g,"");const match=[...whatsappCountryCodes].sort((a,b)=>b.code.length-a.code.length).find(item=>digits.startsWith(item.code.replace("+","")));return {countryCode:match?.code||"+62",localNumber:(match?digits.slice(match.code.replace("+","").length):digits).replace(/^0+/,"")}};

function Avatar(_props:{text:string;tone?:string;imageKey?:string}) { return null; }
function ProductBadge({ product }:{product:string}) { return <span className={productClass(product)}><i />{product}</span>; }
function Status({ children }:{children:string}) { return <span className={badgeClass(children)}><i />{children}</span>; }
function Metric({ label,value,delta,icon,tone }:{label:string;value:string;delta:string;icon:string;tone:string}) { return <article className="metric-card"><div className={`metric-icon ${tone}`}>{icon}</div><div><p>{label}</p><strong>{value}</strong><small>{delta}</small></div></article>; }
function SocialAccounts({application}:{application:Application}){const accounts=[{name:"TikTok",url:application.tiktokUrl,tier:application.tiktokFollowers,icon:"/social/tiktok.png"},{name:"Instagram",url:application.instagramUrl,tier:application.instagramFollowers,icon:"/social/instagram.png"},{name:"Threads",url:application.threadsUrl,tier:application.threadsFollowers,icon:"/social/threads.png"}].filter(account=>account.url);return <div className="social-account-list">{accounts.length?accounts.map(account=>{let username=application.handle;try{username=new URL(account.url||"").pathname.split("/").filter(Boolean).at(-1)||application.handle}catch{}return <a key={account.name} href={account.url} target="_blank" rel="noreferrer"><img className="social-platform-icon" src={account.icon} alt={`${account.name} logo`}/><b>{username.startsWith("@")?username:"@"+username}</b><small>{account.tier||"Followers not provided"}</small></a>}):<span className="no-social-account">No social accounts provided</span>}</div>}

export default function CreatorPoolApp(){
  return <PortalLanguageProvider><CreatorPoolWorkspace/></PortalLanguageProvider>;
}

function CreatorPoolWorkspace(){
  const [space,setSpace]=useState<Space>("public");
  const [page,setPage]=useState("Public");
  const [modal,setModal]=useState<Modal>(null);
  const [apps,setApps]=useState<Application[]>(seedApplications);
  const [taskRows,setTasks]=useState<Task[]>(seedTasks);
  const [subs,setSubs]=useState<Submission[]>(seedSubmissions);
  const [appExpansionRequests,setAppExpansionRequests]=useState<AppExpansionRequest[]>([]);
  const [streakRequests,setStreakRequests]=useState<StreakRequest[]>(seedStreakRequests);
  const [paymentForms,setPaymentForms]=useState<PaymentForm[]>(seedPaymentForms);
  const [creatorProfiles,setCreatorProfiles]=useState<CreatorProfile[]>(seedCreatorProfiles);
  const [rewardRows,setRewards]=useState<Reward[]>(seedRewards);
  const [selected,setSelected]=useState<Submission>(seedSubmissions[0]);
  const [selectedTask,setSelectedTask]=useState<Task>(seedTasks[0]);
  const [submissionTaskId,setSubmissionTaskId]=useState(seedTasks[0]?.id||"");
  const [toast,setToast]=useState("");
  const [mobileNav,setMobileNav]=useState(false);
  const [teamProfileMenu,setTeamProfileMenu]=useState(false);
  const [account,setAccount]=useState<Account|null>(null);
  const [joinedCampaignIds,setJoinedCampaignIds]=useState<string[]>([]);

  useEffect(()=>{ fetch("/api/platform").then(r=>r.ok?r.json():null).then(data=>{ if(!data)return; if(data.applications?.length)setApps(data.applications.map((item:Application)=>({...item,status:applicationStatus(item.status),category:categoryList(item.category).slice(0,3).join(", ")}))); if(data.tasks?.length)setTasks(data.tasks.map((item:Task)=>({...item,niches:taskNiches(item).join(",")}))); if(data.submissions?.length)setSubs(data.submissions.map((item:Submission)=>({...item,status:normalizeSubmissionStatus(item.status)}))); if(data.appExpansionRequests?.length)setAppExpansionRequests(data.appExpansionRequests); if(data.streakRequests?.length)setStreakRequests(data.streakRequests); if(data.paymentForms?.length)setPaymentForms(data.paymentForms); if(data.creatorProfiles?.length)setCreatorProfiles(data.creatorProfiles.map((profile:CreatorProfile)=>({...profile,niches:categoryList(profile.niches).slice(0,3).join(",")}))); if(data.rewards?.length)setRewards(data.rewards.map(normalizeRewardStatus)); }).catch(()=>{}); },[]);
  useEffect(()=>{if(!supabase)return;let live=true;const loadAccount=async(user:{id:string;email?:string|null}|null)=>{if(!user){if(live)setAccount(null);return}const {data}=await supabase.from("profiles").select("role, application_status").eq("id",user.id).maybeSingle();if(!live)return;setAccount({id:user.id,email:user.email||"",role:data?.role==="marketing_admin"?"team":"creator",applicationStatus:data?.application_status==="accepted"||data?.application_status==="declined"?data.application_status:"in_review"})};void supabase.auth.getUser().then(({data})=>void loadAccount(data.user));const {data:{subscription}}=supabase.auth.onAuthStateChange((_event,session)=>{void loadAccount(session?.user||null)});return()=>{live=false;subscription.unsubscribe()}},[]);
  useEffect(()=>{if(account&&typeof window!=="undefined"&&window.sessionStorage.getItem("creatorhub-open-application")==="true"){window.sessionStorage.removeItem("creatorhub-open-application");setModal("application")}},[account]);
  useEffect(()=>{if(!supabase||!account)return;void supabase.from("creator_applications").select("id,status,decline_reason,submitted_at,application_data").order("submitted_at",{ascending:false}).then(({data})=>{if(data)setApps(data.map(storedApplication))})},[account]);
  useEffect(()=>{if(!supabase||!account)return;void supabase.from("creator_profile_settings").select("creator_id,display_name,contact_email,niches,tiktok_url,instagram_url,threads_url,whatsapp,avatar_key,avatar_name,updated_at").eq("creator_id",account.id).maybeSingle().then(({data})=>{if(data){const profile=storedCreatorSettings(data);setCreatorProfiles(items=>[profile,...items.filter(item=>item.creator!==currentCreator)])}})},[account]);
  useEffect(()=>{if(!supabase||!account)return;let live=true;const loadCampaigns=async()=>{const {data:campaigns,error}=await supabase.from("campaigns").select("id,title,product,reference_link,tutorial_link,deadline,status,task_data").order("created_at",{ascending:false});if(!live)return;if(error){notify("Unable to load campaigns. Please refresh and try again.");return}if(campaigns)setTasks(campaigns.map(storedCampaign));if(account.role==="creator"){const {data:{user}}=await supabase.auth.getUser();if(!user||!live)return;const {data:joins}=await supabase.from("creator_campaign_joins").select("campaign_id").eq("creator_id",user.id);if(live)setJoinedCampaignIds((joins||[]).map(join=>join.campaign_id));}};void loadCampaigns();return()=>{live=false}},[account]);
  const notify=(message:string)=>{setToast(message); window.setTimeout(()=>setToast(""),3200)};
  const persist=(entity:string,item:unknown)=>fetch("/api/platform",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({entity,item})}).catch(()=>null);
  const remove=(entity:string,id:string)=>fetch("/api/platform",{method:"DELETE",headers:{"content-type":"application/json"},body:JSON.stringify({entity,id})}).catch(()=>null);
  async function saveRealApplication(application:Application){
    if(!supabase)throw new Error("Sign in is required before sending an application.");
    const {data:{user}}=await supabase.auth.getUser();
    if(!user)throw new Error("Please sign in before sending an application.");
    const {data,error}=await supabase.from("creator_applications").insert({creator_id:user.id,application_data:application}).select("id,status,decline_reason,submitted_at,application_data").single();
    if(error)throw new Error(error.message);
    setApps(items=>[storedApplication(data),...items.filter(item=>item.id!==data.id)]);
  }
  const navigate=(label:string)=>{setPage(label);setMobileNav(false);setTeamProfileMenu(false)};
  const nav=space==="creator"?creatorNav:teamNav;
  const creatorApplication=apps.find(a=>a.name===currentCreator);
  const creatorProfile=creatorProfiles.find(profile=>profile.creator===currentCreator)||seedCreatorProfiles[0];
  const approvedExpansionProducts=appExpansionRequests.filter(request=>request.creator===currentCreator&&request.status==="Accepted").flatMap(request=>request.requestedApps.split(",").filter(Boolean) as Product[]);
  const creatorProducts=([...new Set([...(creatorApplication?.interestedApps?.split(",").filter(Boolean)||[creatorApplication?.product||"Meitu"]),...approvedExpansionProducts])] as Product[]);
  const creatorTaskRows=taskRows.filter(task=>creatorProducts.includes(task.product));
  const creatorSubmissionTasks=creatorTaskRows.filter(task=>taskStatusFor(task)==="Ongoing");

  function switchSpace(next:Space){
    if(next==="public"){setSpace("public");setPage("Public");setTeamProfileMenu(false);return}
    if(!account){notify("Please sign in to access your portal.");setSpace("public");setModal("auth");return}
    if(next==="team"&&account.role!=="team"){notify("This account does not have Team access.");return}
    if(next==="creator"&&(account.role!=="creator"||account.applicationStatus!=="accepted")){notify(account.applicationStatus==="declined"?"This creator application was not accepted.":"Your creator application is still in review.");return}
    setSpace(next);setPage(next==="team"?"Overview":"Home");setTeamProfileMenu(false);
  }
  function decide(status:string){ const updated={...selected,status}; setSelected(updated); setSubs(s=>s.map(x=>x.id===updated.id?updated:x)); persist("submission",updated); const tier=rewardTierForViews(updated.views); notify(status==="Approved"?(tier?`Submission qualified — ${tier.reward} reward calculated.`:"Submission qualified — views belum mencapai reward tier."):"Not Qualified decision sent to creator."); setModal(null); if(status==="Approved"&&tier&&!rewardRows.some(r=>r.id===`RWD-${updated.id.slice(-4)}`)){ const r:Reward={id:`RWD-${updated.id.slice(-4)}`,submissionId:updated.id,creator:updated.creator,task:updated.task,product:updated.product,views:updated.views,type:tier.amount?"Cash":tier.reward,amount:tier.amount,status:tier.amount?"Please Fill In Payment Form":"Approved",paymentFormChecked:0}; setRewards(v=>[r,...v]);persist("reward",r); }}
  function qualifySubmission(item:Submission){const updated={...item,status:"Qualified",qualificationReason:""};setSubs(v=>v.map(row=>row.id===item.id?updated:row));persist("submission",updated);const tier=rewardTierForViews(updated.views);if(tier&&tier.views>=10000&&!rewardRows.some(row=>row.submissionId===item.id)){const reward:Reward={id:`RWD-${Date.now().toString().slice(-6)}`,submissionId:item.id,creator:item.creator,task:item.task,product:item.product,views:item.views,type:tier.amount?"Cash":tier.reward,amount:tier.amount,status:tier.amount?"Please Fill In Payment Form":"Approved",paymentFormChecked:0};setRewards(v=>[reward,...v]);persist("reward",reward)}notify(tier&&tier.views>=10000?`Qualified — reward ${tier.reward} ditambahkan ke Rewards. Analytics screenshot remains available to the Team.`:"Qualified — analytics screenshot remains available to the Team.")}
  function removeLinkedReward(submissionId:string){const linked=rewardRows.find(reward=>reward.submissionId===submissionId);if(!linked)return;setRewards(rows=>rows.filter(reward=>reward.id!==linked.id));remove("reward",linked.id)}
  function notQualifySubmission(item:Submission,reason:string){const updated={...item,status:"Not Qualified",qualificationReason:reason};setSubs(v=>v.map(row=>row.id===item.id?updated:row));persist("submission",updated);removeLinkedReward(item.id);notify("Submission marked Not Qualified. Its analytics screenshot remains available to the Team and any linked reward was removed.")}
  function reopenSubmission(item:Submission){const updated={...item,status:"In review",qualificationReason:""};setSubs(v=>v.map(row=>row.id===item.id?updated:row));persist("submission",updated);removeLinkedReward(item.id);notify("Submission moved back to In Review and its linked reward was paused.")}
  function updateEngagementRate(item:Submission,rate:number){const updated={...item,engagementRate:rate,analyticsStatus:"Manual override"};setSubs(rows=>rows.map(row=>row.id===item.id?updated:row));persist("submission",updated);notify(`Engagement rate for ${item.creator} updated to ${rate.toFixed(2)}%.`)}
  async function saveTask(task:Task){
    if(!supabase){notify("Supabase is not configured.");return}
    const {data:{user}}=await supabase.auth.getUser();
    if(!user){notify("Please sign in with a Team account before saving a campaign.");return}
    const record={title:task.title,product:task.product,reference_link:task.referenceLink||null,tutorial_link:task.tutorialLink||null,deadline:`${task.deadline}T23:59:59+00:00`,status:task.status==="Draft"?"draft":task.status==="Closed"?"closed":"active",task_data:{...task,id:undefined},created_by:user.id};
    const existing=taskRows.some(row=>row.id===task.id&&/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(row.id));
    const request=existing?supabase.from("campaigns").update(record).eq("id",task.id):supabase.from("campaigns").insert(record);
    const {data,error}=await request.select("id,title,product,reference_link,tutorial_link,deadline,status,task_data").single();
    if(error){notify(`Campaign could not be saved: ${error.message}`);return}
    const saved=storedCampaign(data);
    setTasks(rows=>existing?rows.map(row=>row.id===saved.id?saved:row):[saved,...rows]);
    setModal(null);notify(`Campaign ${saved.title} berhasil ${existing?"diperbarui":"dipublikasikan"}.`);
  }
  async function joinCampaign(task:Task){
    if(!supabase){notify("Supabase is not configured.");return}
    const {data:{user}}=await supabase.auth.getUser();
    if(!user){notify("Please sign in before joining a campaign.");return}
    if(joinedCampaignIds.includes(task.id)){setSubmissionTaskId(task.id);setModal("submission");return}
    const {error}=await supabase.from("creator_campaign_joins").insert({campaign_id:task.id,creator_id:user.id});
    if(error&&error.code!=="23505"){notify(`Unable to join campaign: ${error.message}`);return}
    setJoinedCampaignIds(ids=>ids.includes(task.id)?ids:[...ids,task.id]);
    notify(`You have joined ${task.title}. You can now submit your post.`);
  }
  function updateReward(reward:Reward){setRewards(rows=>rows.map(row=>row.id===reward.id?reward:row));persist("reward",reward)}
  function exportCsv(){ const ready=rewardRows.filter(r=>r.amount>0&&r.paymentFormChecked); const csv=["Reward ID,Submission ID,Creator,Campaign,Product,Qualified views,Amount,Currency,Status",...ready.map(r=>[r.id,r.submissionId,r.creator,r.task,r.product,r.views,r.amount,"IDR",r.status].join(","))].join("\n"); const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([csv],{type:"text/csv"}));a.download="creator-pool-payment-tracker.csv";a.click();notify(`${ready.length} payment-ready rewards exported to CSV.`); }

  if(space==="public") return <PublicSite onSignIn={()=>setModal("auth")} onApply={()=>{if(account){setModal("application");return}window.sessionStorage.setItem("creatorhub-open-application","true");setModal("auth")}} onOpenPortal={()=>switchSpace(account?.role==="team"?"team":"creator")} modal={modal} setModal={setModal} notify={notify} persist={persist} setApps={setApps} saveApplication={saveRealApplication} toast={toast} account={account} onSignOut={async()=>{if(supabase)await supabase.auth.signOut();setAccount(null);notify("You have signed out.")}}/>;

  return <div className={`app-shell app-shell-${space}`}>
    <aside className={`sidebar ${mobileNav?"open":""}`}>
      <button className="brand" onClick={()=>navigate(space==="team"?"Overview":"Home")} aria-label="CreatorHub home"><img className="brand-logo" src="/canva/meitu-app.png" alt="Meitu"/><span className="brand-title">CreatorHub</span></button>
      <div className="space-switch"><button className={space==="team"?"active":""} onClick={()=>switchSpace("team")}>Team</button><button className={space==="creator"?"active":""} onClick={()=>switchSpace("creator")}>Creator</button></div>
      <p className="nav-label">{space==="team"?"Workspace":"Ruang kreator"}</p>
      <nav>{nav.map(([label,icon])=><button key={label} className={page===label?"active":""} onClick={()=>navigate(label)}><span>{icon}</span>{label}{label==="Applications"&&<em>8</em>}{label==="Submissions"&&<em>12</em>}</button>)}</nav>
      <div className="sidebar-bottom">
        {space==="creator"&&<button onClick={()=>setModal("new-apps")}><span>＋</span>Apply New Apps</button>}
        <button onClick={()=>switchSpace("public")}><span>↗</span>Public site</button>
        {space==="team"&&<button onClick={()=>notify("Team settings tetap menggunakan konfigurasi workspace saat ini.")}><span>⚙</span>Settings</button>}
        <div className="user-chip"><div><b>{space==="team"?"Alya Rahman":"Salsa Nabila"}</b><small>{space==="team"?"Admin · Indonesia":"Priority creator"}</small></div><span>···</span></div>
      </div>
    </aside>
    {mobileNav&&<button className="nav-scrim" aria-label="Close menu" onClick={()=>setMobileNav(false)}/>} 
    <main>
      <header className="topbar"><button className="menu-button" onClick={()=>setMobileNav(true)} aria-label="Open menu">☰</button><div className="top-actions"><PortalProfileMenu space={space} open={teamProfileMenu} setOpen={setTeamProfileMenu} creatorProfile={creatorProfile} onProfile={()=>{setTeamProfileMenu(false);if(space==="team")setModal("team-profile");else navigate("Profile")}} onLogout={()=>{setTeamProfileMenu(false);switchSpace("public");notify(`You have logged out of the ${space==="team"?"Team":"Creator"} Portal.`)}}/></div></header>
      <div className="workspace">
        {space==="team"&&page==="Overview"&&<Overview onNavigate={navigate} submissions={subs} applications={apps} rewards={rewardRows} tasks={taskRows}/>}
        {space==="team"&&page==="Applications"&&<ApplicationsHub rows={apps} expansionRequests={appExpansionRequests} streakRequests={streakRequests} setApps={setApps} setExpansionRequests={setAppExpansionRequests} setStreakRequests={setStreakRequests} notify={notify} persist={persist}/>}
        {space==="team"&&page==="Creators"&&<Creators applications={apps.filter(a=>a.status==="Accepted")} submissions={subs} profiles={creatorProfiles}/>}
        {page==="Campaigns"&&<Tasks creator={space==="creator"} rows={taskRows} creatorCategories={categoryList(creatorProfile?.niches||creatorApplication?.category||"Beauty")} creatorProducts={creatorProducts} joinedCampaignIds={joinedCampaignIds} onCreate={()=>setModal("task")} onPreview={task=>{setSelectedTask(task);setModal("task-preview")}} onManage={task=>{setSelectedTask(task);setModal("edit-task")}} onJoin={joinCampaign} onSubmit={task=>{setSubmissionTaskId(task.id);setModal("submission")}}/>}
        {page==="Submissions"&&<ManualSubmissions creator={space==="creator"} rows={subs} tasks={taskRows} rewards={rewardRows} paymentForms={paymentForms} onCreate={()=>setModal("submission")} onRewards={()=>navigate("Rewards")} onQualified={qualifySubmission} onNotQualified={notQualifySubmission} onReopen={reopenSubmission} onUpdateEngagement={updateEngagementRate}/>}
        {page==="Rewards"&&<EnhancedRewards creator={space==="creator"} rows={rewardRows} tasks={taskRows} submissions={subs} paymentForms={paymentForms} update={updateReward} exportCsv={exportCsv}/>}
        {space==="team"&&page==="Payment Forms"&&<PaymentForms forms={paymentForms} setForms={setPaymentForms} notify={notify} persist={persist} remove={remove}/>}
        {space==="creator"&&page==="Home"&&<CreatorHome navigate={navigate} profile={creatorProfile} tasks={creatorTaskRows} submissions={subs} rewards={rewardRows} requests={streakRequests.filter(request=>request.creator===currentCreator)} saveRequest={request=>{setStreakRequests(rows=>rows.some(item=>item.id===request.id)?rows.map(item=>item.id===request.id?request:item):[request,...rows]);persist("streakRequest",request);notify("Pilihan VIP berhasil dikirim ke Team untuk approval. Streak berikutnya dimulai dari nol.")}}/>}
        {space==="creator"&&page==="Leaderboard"&&<Leaderboard profiles={creatorProfiles} tasks={taskRows} submissions={subs} applications={apps} expansionRequests={appExpansionRequests} rewards={rewardRows}/>}
        {space==="creator"&&page==="Profile"&&<Profile profile={creatorProfile} save={async profile=>{if(!supabase||!account)throw new Error("Please sign in before saving your profile.");const {error}=await supabase.from("creator_profile_settings").upsert({creator_id:account.id,display_name:profile.displayName||"",contact_email:profile.contactEmail||"",niches:profile.niches,tiktok_url:profile.tiktokUrl||null,instagram_url:profile.instagramUrl||null,threads_url:profile.threadsUrl||null,whatsapp:profile.whatsapp||null,avatar_key:profile.avatarKey||null,avatar_name:profile.avatarName||null,updated_at:new Date().toISOString()});if(error)throw new Error(error.message);const saved={...profile,id:account.id};setCreatorProfiles(items=>[saved,...items.filter(item=>item.creator!==currentCreator)]);notify("Profile saved. Your changes are now visible across CreatorHub.")}}/>}
      </div>
    </main>
    {modal==="task"&&<TaskModal close={()=>setModal(null)} save={saveTask}/>} 
    {modal==="edit-task"&&<TaskModal task={selectedTask} close={()=>setModal(null)} save={saveTask}/>} 
    {modal==="task-preview"&&<TaskPreview creator={space==="creator"} task={selectedTask} submissions={subs} close={()=>setModal(null)} manage={()=>setModal("edit-task")}/>} 
    {modal==="submission"&&<SubmissionModal close={()=>setModal(null)} tasks={creatorSubmissionTasks} initialTaskId={submissionTaskId} save={(s)=>{setSubs(v=>[s,...v]);persist("submission",s);setModal(null);notify(s.status==="Draft"?"Draft kiriman berhasil disimpan.":"Analytics verified and submission sent for Team review.")}}/>}
    {modal==="new-apps"&&<ApplyAppsModal currentApps={creatorProducts} requests={appExpansionRequests.filter(request=>request.creator===currentCreator)} close={()=>setModal(null)} save={(request)=>{setAppExpansionRequests(v=>[request,...v]);persist("appExpansion",request);setModal(null);notify("Pengajuan aplikasi baru berhasil dikirim untuk review.")}}/>}
    {modal==="review"&&<ManualReviewDrawer item={selected} close={()=>setModal(null)} decide={decide}/>}
    {modal==="team-profile"&&<div className="modal-layer"><button className="modal-scrim" onClick={()=>setModal(null)} aria-label="Close team profile"/><section className="dialog team-profile-dialog"><header><div><span className="eyebrow">Team profile</span><h2>Alya Rahman</h2><p>Creator Pool administrator · Indonesia</p></div><button className="close" onClick={()=>setModal(null)}>×</button></header><div className="team-profile-details"><dl><div><dt>Name</dt><dd>Alya Rahman</dd></div><div><dt>Role</dt><dd>Administrator</dd></div><div><dt>Workspace</dt><dd>Meitu Creator Pool Indonesia</dd></div></dl></div><footer><button className="primary" onClick={()=>setModal(null)}>Done</button></footer></section></div>}
    {toast&&<div className="toast"><span>✓</span>{toast}</div>}
  </div>;
}

function PageHead({eyebrow,title,copy,children}:{eyebrow?:string;title:string;copy:string;children?:React.ReactNode}){return <div className="page-head"><div>{eyebrow&&<span className="eyebrow">{eyebrow}</span>}<h1>{title}</h1><p>{copy}</p></div>{children&&<div className="head-actions">{children}</div>}</div>}

function PortalProfileMenu({space,open,setOpen,creatorProfile,onProfile,onLogout}:{space:"team"|"creator";open:boolean;setOpen:React.Dispatch<React.SetStateAction<boolean>>;creatorProfile:CreatorProfile;onProfile:()=>void;onLogout:()=>void}){
  const creator=space==="creator";
  return <div className={`team-profile-control ${creator?"creator-profile-control":""}`}><button className="team-profile-trigger profile-text-trigger" onClick={()=>setOpen(value=>!value)} aria-expanded={open} aria-label={`Open ${space} profile menu`}>Account</button>{open&&<><button className="profile-menu-scrim" onClick={()=>setOpen(false)} aria-label="Close profile menu"/><div className="team-profile-dropdown" role="menu"><div className="portal-profile-summary"><span><b>{creator?creatorProfile?.displayName||currentCreator:"Alya Rahman"}</b><small>{creator?"Creator account":"Team administrator"}</small></span></div><button onClick={onProfile}><span>Profile</span><b>›</b></button><div className="team-profile-language"><span>Language</span><PortalLanguageSwitcher/></div><hr/><button onClick={onLogout}><span>Log out</span></button></div></>}</div>;
}

function Overview({onNavigate,submissions,applications,rewards,tasks}:{onNavigate:(p:string)=>void;submissions:Submission[];applications:Application[];rewards:Reward[];tasks:Task[]}){
  const applicationsToReview=applications.filter(item=>applicationStatus(item.status)==="In review").length;
  const totalCreators=applications.filter(item=>applicationStatus(item.status)==="Accepted").length;
  const submissionsInQueue=submissions.filter(item=>normalizeSubmissionStatus(item.status)==="In review").length;
  const activity=[{month:"Feb",values:[50,32,22]},{month:"Mar",values:[72,43,31]},{month:"Apr",values:[82,58,43]},{month:"May",values:[91,67,52]},{month:"Jun",values:[103,78,59]},{month:"Jul",values:[121,97,70]},{month:"Aug",values:[134,114,84]}];
  const activityApps=["Meitu","BeautyCam","Wink"];
  const activityMax=140;
  return <>
    <PageHead title="Good morning, Alya" copy="Here’s your Creator Pool performance overview."/>
    <section className="overview-tab-cards" aria-label="Team overview shortcuts">
      <button className="overview-tab-card overview-tab-accent" onClick={()=>onNavigate("Applications")}><span><small>Applications to review</small><strong>{applicationsToReview}</strong><em>Open applications</em></span><b aria-hidden="true">↗</b></button>
      <button className="overview-tab-card" onClick={()=>onNavigate("Creators")}><span><small>Total creators</small><strong>{totalCreators}</strong><em>Open creators</em></span><b aria-hidden="true">↗</b></button>
      <button className="overview-tab-card overview-tab-dark" onClick={()=>onNavigate("Submissions")}><span><small>Submissions in queue</small><strong>{submissionsInQueue}</strong><em>Open submissions</em></span><b aria-hidden="true">↗</b></button>
    </section>
    <section className="panel chart-panel overview-activity"><div className="panel-head"><div><h2>Creator activity</h2><p>Qualified submissions across products</p></div><div className="legend"><span><i className="meitu-dot"/>Meitu</span><span><i className="beauty-dot"/>BeautyCam</span><span><i className="wink-dot"/>Wink</span></div></div><div className="chart"><div className="y-axis"><span>140</span><span>105</span><span>70</span><span>35</span><span>0</span></div><div className="bars">{activity.map(({month,values})=><div className="bar-group" key={month}><div>{values.map((value,index)=><i tabIndex={0} role="img" aria-label={`${activityApps[index]}: ${value} qualified submissions in ${month}`} style={{height:`${value/activityMax*100}%`}} className={["bar-meitu","bar-beauty","bar-wink"][index]} key={activityApps[index]}><span className="chart-bar-tooltip">{activityApps[index]} · {value}</span></i>)}</div><span>{month}</span></div>)}</div></div></section>
    <div className="overview-reports"><ManualReports submissions={submissions} rewards={rewards} tasks={tasks}/></div>
  </>;
}

function SubmissionTable({rows,onRow}:{rows:Submission[];onRow:(s:Submission)=>void}){return <div className="table-wrap"><table className="creator-summary-table"><thead><tr><th>Creator</th><th>Campaign</th><th>Product</th><th>Verified views</th><th>AI recommendation</th><th>Confidence</th><th>Status</th><th/></tr></thead><tbody>{rows.map(s=><tr key={s.id} onClick={()=>onRow(s)}><td><div className="creator-cell"><span><b>{s.creator}</b><small>{s.platform} · {s.id}</small></span></div></td><td><b>{s.task}</b><small>{s.submitted}</small></td><td><ProductBadge product={s.product}/></td><td><b>{fmtNum(s.aiViews)}</b><small>{Math.abs(s.views-s.aiViews)/s.views>.05?"Mismatch flagged":"Evidence matched"}</small></td><td><span className={`recommend recommend-${s.recommendation.toLowerCase()}`}>{s.recommendation==="Approve"?"✓":s.recommendation==="Revision"?"↻":"!"} {s.recommendation}</span></td><td><div className="confidence"><span><i style={{width:`${s.confidence}%`}}/></span><b>{s.confidence}%</b></div></td><td><Status>{s.status}</Status></td><td><button type="button" className="table-row-open-button" aria-label={`Review ${s.creator}`} onClick={event=>{event.stopPropagation();onRow(s)}}>›</button></td></tr>)}</tbody></table></div>}

function Applications({rows,expansionRequests,setApps,setExpansionRequests,notify,persist,initialView="Creator applications"}:{rows:Application[];expansionRequests:AppExpansionRequest[];setApps:React.Dispatch<React.SetStateAction<Application[]>>;setExpansionRequests:React.Dispatch<React.SetStateAction<AppExpansionRequest[]>>;notify:(s:string)=>void;persist:(e:string,i:unknown)=>void;initialView?:"Creator applications"|"Apply New Apps"}){
  type ReviewStatus="In review"|"Accepted"|"Declined";
  const [applicationView,setApplicationView]=useState<"Creator applications"|"Apply New Apps">(initialView);
  const [creatorFilter,setCreatorFilter]=useState<ReviewStatus>("In review");
  const [expansionFilter,setExpansionFilter]=useState<ReviewStatus>("In review");
  const [query,setQuery]=useState("");
  const [expansionQuery,setExpansionQuery]=useState("");
  const [platformFilter,setPlatformFilter]=useState("All");
  const [followersFilter,setFollowersFilter]=useState("All");
  const [appFilter,setAppFilter]=useState("All");
  const [expansionAppFilter,setExpansionAppFilter]=useState("All");
  const [sort,setSort]=useState("Newest first");
  const [expansionSort,setExpansionSort]=useState("Newest first");
  const [expanded,setExpanded]=useState<string|null>(null);
  const [expandedExpansion,setExpandedExpansion]=useState<string|null>(null);
  const [declining,setDeclining]=useState<Application|null>(null);
  const [decliningExpansion,setDecliningExpansion]=useState<AppExpansionRequest|null>(null);
  const [editingApplication,setEditingApplication]=useState<Application|null>(null);
  const [editingExpansion,setEditingExpansion]=useState<AppExpansionRequest|null>(null);
  const [decisionStatus,setDecisionStatus]=useState<ReviewStatus>("In review");
  const [declineReason,setDeclineReason]=useState("");
  const tabs:ReviewStatus[]=["In review","Accepted","Declined"];
  const followerRanges=["All","< 10.000 Followers","10.000 - 50.000 Followers","50.000 - 100.000 Followers","100.000 - 250.000 Followers","250.000 - 500.000 Followers","> 500.000 Followers"];
  const creatorApplications=rows;
  const filtered=creatorApplications.filter(row=>{
    const searchable=(row.name+" "+(row.email||"")+" "+row.handle).toLowerCase();
    const platforms=[row.tiktokUrl&&"TikTok",row.instagramUrl&&"Instagram",row.threadsUrl&&"Threads"].filter(Boolean);
    const apps=(row.interestedApps||row.product).split(",");
    const tiers=[row.tiktokFollowers,row.instagramFollowers,row.threadsFollowers].filter(Boolean);
    return applicationStatus(row.status)===creatorFilter&&searchable.includes(query.toLowerCase())&&(platformFilter==="All"||platforms.includes(platformFilter))&&(followersFilter==="All"||tiers.includes(followersFilter))&&(appFilter==="All"||apps.includes(appFilter));
  }).sort((a,b)=>sort==="Highest followers first"?followerCount(b)-followerCount(a):creatorApplications.indexOf(a)-creatorApplications.indexOf(b));
  const expansionCreator=(request:AppExpansionRequest)=>rows.find(row=>row.name===request.creator);
  const expansionFiltered=expansionRequests.filter(request=>{
    const creator=expansionCreator(request);
    const searchable=(request.creator+" "+(creator?.email||"")+" "+(creator?.handle||"")+" "+request.requestedApps).toLowerCase();
    return request.status===expansionFilter&&searchable.includes(expansionQuery.toLowerCase())&&(expansionAppFilter==="All"||request.requestedApps.split(",").includes(expansionAppFilter));
  }).sort((a,b)=>expansionSort==="Oldest first"?new Date(a.submitted).getTime()-new Date(b.submitted).getTime():new Date(b.submitted).getTime()-new Date(a.submitted).getTime());
  const move=async(row:Application,status:ReviewStatus,reason="")=>{const updated={...row,status,declineReason:status==="Declined"?reason:""};if(supabase){const dbStatus=status==="Accepted"?"accepted":status==="Declined"?"declined":"in_review";const {data,error}=await supabase.from("creator_applications").update({status:dbStatus,decline_reason:status==="Declined"?reason:null,reviewed_at:new Date().toISOString()}).eq("id",row.id).select("creator_id").single();if(error){notify(error.message);return}await supabase.from("profiles").update({application_status:dbStatus}).eq("id",data.creator_id)}setApps(items=>items.map(item=>item.id===row.id?updated:item));setExpanded(null);notify(status==="Accepted"?row.name+" accepted and added to Creators.":status==="Declined"?row.name+" declined. The reason is ready for the creator notification.":row.name+" moved back to In review.")};
  const updateExpansion=(request:AppExpansionRequest,status:ReviewStatus,reason="")=>{const updated={...request,status,declineReason:status==="Declined"?reason:""};const nextRequests=expansionRequests.map(item=>item.id===request.id?updated:item);setExpansionRequests(nextRequests);persist("appExpansion",updated);const creator=rows.find(item=>item.name===request.creator);if(creator){const base=request.currentApps.split(",").filter(Boolean);const approved=nextRequests.filter(item=>item.creator===request.creator&&item.status==="Accepted").flatMap(item=>item.requestedApps.split(",").filter(Boolean));const creatorUpdate={...creator,interestedApps:[...new Set([...base,...approved])].join(",")};setApps(items=>items.map(item=>item.id===creator.id?creatorUpdate:item));persist("application",creatorUpdate)}setExpandedExpansion(null);notify(status==="Accepted"?request.requestedApps+" access approved for "+request.creator+".":status==="Declined"?"New app request from "+request.creator+" declined.":request.creator+"’s app request moved back to In review.")};
  const closeDecline=()=>{setDeclining(null);setDecliningExpansion(null);setDeclineReason("")};
  const openApplicationDecision=(application:Application)=>{setEditingApplication(application);setEditingExpansion(null);setDecisionStatus(applicationStatus(application.status) as ReviewStatus);setDeclineReason(application.declineReason||"")};
  const openExpansionDecision=(request:AppExpansionRequest)=>{setEditingExpansion(request);setEditingApplication(null);setDecisionStatus(request.status as ReviewStatus);setDeclineReason(request.declineReason||"")};
  const closeDecisionEditor=()=>{setEditingApplication(null);setEditingExpansion(null);setDeclineReason("")};
  const creatorTable=<section className="panel application-table-card">{filtered.length===0?<div className="application-empty"><span>◎</span><b>No matching applications</b><p>Try changing one or more filters.</p></div>:<div className="table-wrap"><table className="application-table manual-application-table"><thead><tr><th>Creator</th><th>Contact</th><th>Social Media</th><th>Target Apps</th><th>Submitted</th><th>Actions</th></tr></thead>{filtered.map(application=>{const status=applicationStatus(application.status) as ReviewStatus;return <tbody key={application.id}><tr><td data-label="Creator"><div className="creator-cell"><Avatar text={application.avatar} tone="peach"/><span><b>{application.name}</b><small>{application.handle}</small><small>{application.city}, {application.province}</small></span></div></td><td data-label="Contact"><div className="application-contact"><a href={"mailto:"+application.email}>{application.email||"—"}</a>{application.whatsapp?<a href={"https://wa.me/"+application.whatsapp.replace(/\D/g,"")} target="_blank" rel="noreferrer">+{application.whatsapp} ↗</a>:<small>No WhatsApp</small>}</div></td><td data-label="Social Media"><SocialAccounts application={application}/></td><td data-label="Target Apps"><div className="product-stack">{(application.interestedApps||application.product).split(",").map(product=><ProductBadge key={product} product={product}/>)}</div></td><td data-label="Submitted"><div className="submitted-date"><b>{displayDate(application.submitted)}</b><small>{application.id}</small></div></td><td data-label="Actions"><div className="application-actions"><button type="button" className="secondary table-action-button" onClick={()=>setExpanded(current=>current===application.id?null:application.id)}>{expanded===application.id?"Close":"View"}</button>{status==="In review"?<><button type="button" className="primary table-action-button" onClick={()=>move(application,"Accepted")}>Accept</button><button type="button" className="danger table-action-button" onClick={()=>{setDeclining(application);setDeclineReason("")}}>Decline</button></>:<><button type="button" className="secondary table-action-button" onClick={()=>openApplicationDecision(application)}>Edit</button><button type="button" className="application-undo-button table-action-button" onClick={()=>move(application,"In review")}>Undo</button></>}</div></td></tr>{expanded===application.id&&<tr className="application-answer-row"><td colSpan={6}><div className="application-answers"><div className="answers-head"><div><span className="eyebrow">Application answers · {application.id}</span><h3>Creative profile: {application.name}</h3></div><small>Submitted {application.submitted}</small></div>{status==="Declined"&&application.declineReason&&<div className="decline-reason-summary"><b>Decline reason sent to creator</b><p>{application.declineReason}</p></div>}<div className="answer-grid"><article><span>01</span><div><b>What features do you usually use on Meitu/Wink/BeautyCam to edit photos/videos?</b><p>{application.featuresUsed||"No answer submitted."}</p></div></article><article><span>02</span><div><b>What makes you more interested in becoming a Meitu Creator?</b><ul className="motivation-answer-list">{(application.motivation||"No answer submitted.").split(" • ").map(answer=><li key={answer}>{answer}</li>)}</ul></div></article><article><span>03</span><div><b>Any impressions, messages, or questions for Meitu and the team?</b><p>{application.impressions||"No answer submitted."}</p></div></article></div></div></td></tr>}</tbody>})}</table></div>}</section>;
  const expansionTable=<section className="panel application-table-card">{expansionFiltered.length===0?<div className="application-empty"><span>＋</span><b>No matching app requests</b><p>Try another search, app, or status.</p></div>:<div className="table-wrap"><table className="application-table manual-application-table expansion-application-table"><thead><tr><th>Creator</th><th>Contact</th><th>Social Media</th><th>Current Apps</th><th>Requested Apps</th><th>Submitted</th><th>Actions</th></tr></thead>{expansionFiltered.map(request=>{const creator=expansionCreator(request);const status=request.status as ReviewStatus;return <tbody key={request.id}><tr><td data-label="Creator"><div className="creator-cell"><Avatar text={request.creator.split(" ").map(part=>part[0]).slice(0,2).join("")} tone="peach"/><span><b>{request.creator}</b><small>{creator?.handle||request.id}</small><small>{creator?[creator.city,creator.province].filter(Boolean).join(", "):"Existing creator"}</small></span></div></td><td data-label="Contact"><div className="application-contact">{creator?.email?<a href={"mailto:"+creator.email}>{creator.email}</a>:<span>—</span>}{creator?.whatsapp?<a href={"https://wa.me/"+creator.whatsapp.replace(/\D/g,"")} target="_blank" rel="noreferrer">+{creator.whatsapp} ↗</a>:<small>No WhatsApp</small>}</div></td><td className="expansion-social-column" data-label="Social Media">{creator?<SocialAccounts application={creator}/>:<span className="no-social-account">No social accounts provided</span>}</td><td data-label="Current Apps"><div className="product-stack">{request.currentApps.split(",").filter(Boolean).map(product=><ProductBadge key={product} product={product}/>)}</div></td><td data-label="Requested Apps"><div className="product-stack">{request.requestedApps.split(",").filter(Boolean).map(product=><ProductBadge key={product} product={product}/>)}</div></td><td data-label="Submitted"><div className="submitted-date"><b>{displayDate(request.submitted)}</b><small>{request.id}</small></div></td><td data-label="Actions"><div className="application-actions"><button type="button" className="secondary table-action-button" onClick={()=>setExpandedExpansion(current=>current===request.id?null:request.id)}>{expandedExpansion===request.id?"Close":"View"}</button>{status==="In review"?<><button type="button" className="primary table-action-button" onClick={()=>updateExpansion(request,"Accepted")}>Accept</button><button type="button" className="danger table-action-button" onClick={()=>{setDecliningExpansion(request);setDeclineReason("")}}>Decline</button></>:<><button type="button" className="secondary table-action-button" onClick={()=>openExpansionDecision(request)}>Edit</button><button type="button" className="application-undo-button table-action-button" onClick={()=>updateExpansion(request,"In review")}>Undo</button></>}</div></td></tr>{expandedExpansion===request.id&&<tr className="application-answer-row"><td colSpan={7}><div className="application-answers expansion-request-answers"><div className="answers-head"><div><span className="eyebrow">App access request · {request.id}</span><h3>{request.creator} requested {request.requestedApps.split(",").join(" · ")}</h3></div><small>Submitted {displayDate(request.submitted)}</small></div>{status==="Declined"&&request.declineReason&&<div className="decline-reason-summary"><b>Decline reason sent to creator</b><p>{request.declineReason}</p></div>}<div className="answer-grid expansion-answer-grid"><article><span>01</span><div><b>Why do you want to join these apps?</b><p>{request.reason}</p></div></article></div></div></td></tr>}</tbody>})}</table></div>}</section>;
  return <><PageHead title="Applications" copy="Review creator applications and app-access requests with a fully manual Team decision."/><div className="segmented application-view-switch manual-application-view-switch"><button className={applicationView==="Creator applications"?"active":""} onClick={()=>setApplicationView("Creator applications")}>Creator applications <span>{creatorApplications.length}</span></button><button className={applicationView==="Apply New Apps"?"active":""} onClick={()=>setApplicationView("Apply New Apps")}>Apply New Apps <span>{expansionRequests.length}</span></button></div>{applicationView==="Creator applications"?<><div className="segmented filters application-status-tabs">{tabs.map(tab=><button className={creatorFilter===tab?"active":""} key={tab} onClick={()=>setCreatorFilter(tab)}>{tab}<span>{creatorApplications.filter(row=>applicationStatus(row.status)===tab).length}</span></button>)}</div><section className="panel application-filter-bar"><label className="application-search"><span>⌕</span><input value={query} onChange={event=>setQuery(event.target.value)} placeholder="Search by name, email or username…"/></label><label>Platforms<select value={platformFilter} onChange={event=>setPlatformFilter(event.target.value)}><option>All</option><option>Instagram</option><option>TikTok</option><option>Threads</option></select></label><label>Followers<select value={followersFilter} onChange={event=>setFollowersFilter(event.target.value)}>{followerRanges.map(range=><option key={range}>{range}</option>)}</select></label><label>Apps<select value={appFilter} onChange={event=>setAppFilter(event.target.value)}><option>All</option><option>Meitu</option><option>BeautyCam</option><option>Wink</option></select></label><label className="application-sort">Sort by<select value={sort} onChange={event=>setSort(event.target.value)}><option>Newest first</option><option>Highest followers first</option></select></label></section>{creatorTable}</>:<><div className="segmented filters application-status-tabs">{tabs.map(tab=><button className={expansionFilter===tab?"active":""} key={tab} onClick={()=>setExpansionFilter(tab)}>{tab}<span>{expansionRequests.filter(request=>request.status===tab).length}</span></button>)}</div><section className="panel application-filter-bar expansion-application-filter"><label className="application-search"><span>⌕</span><input value={expansionQuery} onChange={event=>setExpansionQuery(event.target.value)} placeholder="Search by name, email or username…"/></label><label>Requested app<select value={expansionAppFilter} onChange={event=>setExpansionAppFilter(event.target.value)}><option>All</option><option>Meitu</option><option>BeautyCam</option><option>Wink</option></select></label><label>Sort by<select value={expansionSort} onChange={event=>setExpansionSort(event.target.value)}><option>Newest first</option><option>Oldest first</option></select></label></section>{expansionTable}</>}{declining&&<div className="modal-layer"><button className="modal-scrim" onClick={closeDecline} aria-label="Close decline dialog"/><form className="dialog decline-dialog" onSubmit={event=>{event.preventDefault();const reason=declineReason.trim();if(!reason)return;move(declining,"Declined",reason);closeDecline()}}><header><div><span className="eyebrow">Decline application · {declining.id}</span><h2>Decline {declining.name}?</h2><p>The creator will receive the reason you provide below.</p></div><button type="button" className="close" onClick={closeDecline}>×</button></header><div className="form-body"><div className="decline-creator"><Avatar text={declining.avatar}/><div><b>{declining.name}</b><span>{declining.email||declining.handle} · {declining.city}</span></div></div><label>Reason for declining<textarea autoFocus required value={declineReason} onChange={event=>setDeclineReason(event.target.value)} placeholder="Explain clearly why this application was not accepted…"/><small className="form-help">This reason will be shown to the creator.</small></label></div><footer><button type="button" className="secondary" onClick={closeDecline}>Cancel</button><button type="submit" className="danger" disabled={!declineReason.trim()}>Decline &amp; send reason</button></footer></form></div>}{decliningExpansion&&<div className="modal-layer"><button className="modal-scrim" onClick={closeDecline} aria-label="Close decline dialog"/><form className="dialog decline-dialog" onSubmit={event=>{event.preventDefault();const reason=declineReason.trim();if(!reason)return;updateExpansion(decliningExpansion,"Declined",reason);closeDecline()}}><header><div><span className="eyebrow">Decline app request · {decliningExpansion.id}</span><h2>Decline {decliningExpansion.creator}?</h2><p>The creator will receive the reason you provide below.</p></div><button type="button" className="close" onClick={closeDecline}>×</button></header><div className="form-body"><label>Reason for declining<textarea autoFocus required value={declineReason} onChange={event=>setDeclineReason(event.target.value)} placeholder="Explain why this app-access request was not accepted…"/><small className="form-help">This reason will be shown to the creator.</small></label></div><footer><button type="button" className="secondary" onClick={closeDecline}>Cancel</button><button type="submit" className="danger" disabled={!declineReason.trim()}>Decline &amp; send reason</button></footer></form></div>}{(editingApplication||editingExpansion)&&<div className="modal-layer"><button className="modal-scrim" onClick={closeDecisionEditor} aria-label="Close decision editor"/><form className="dialog decision-edit-dialog" onSubmit={event=>{event.preventDefault();if(decisionStatus==="Declined"&&!declineReason.trim())return;if(editingApplication)move(editingApplication,decisionStatus,declineReason.trim());if(editingExpansion)updateExpansion(editingExpansion,decisionStatus,declineReason.trim());closeDecisionEditor()}}><header><div><span className="eyebrow">Edit decision</span><h2>{editingApplication?.name||editingExpansion?.creator}</h2><p>Change the decision or move this application back into the review queue.</p></div><button type="button" className="close" onClick={closeDecisionEditor}>×</button></header><div className="form-body"><label>Decision<select value={decisionStatus} onChange={event=>{setDecisionStatus(event.target.value as ReviewStatus);if(event.target.value!=="Declined")setDeclineReason("")}}>{tabs.map(tab=><option key={tab}>{tab}</option>)}</select></label>{decisionStatus==="Declined"&&<label>Reason for declining<textarea required value={declineReason} onChange={event=>setDeclineReason(event.target.value)} placeholder="Explain why this application is declined…"/></label>}<div className="decision-history-note"><b>Decision history</b><p>The latest saved decision replaces the current status. Use “In review” to undo the previous action.</p></div></div><footer><button type="button" className="secondary" onClick={closeDecisionEditor}>Cancel</button><button className="primary" disabled={decisionStatus==="Declined"&&!declineReason.trim()}>Save decision</button></footer></form></div>}</>;
}

function ApplicationsHub({rows,expansionRequests,streakRequests,setApps,setExpansionRequests,setStreakRequests,notify,persist}:{rows:Application[];expansionRequests:AppExpansionRequest[];streakRequests:StreakRequest[];setApps:React.Dispatch<React.SetStateAction<Application[]>>;setExpansionRequests:React.Dispatch<React.SetStateAction<AppExpansionRequest[]>>;setStreakRequests:React.Dispatch<React.SetStateAction<StreakRequest[]>>;notify:(message:string)=>void;persist:(entity:string,item:unknown)=>void}){
  type HubView="Creator applications"|"Apply New Apps"|"Streak VIP Code";
  type HubStatus="In review"|"Accepted"|"Declined";
  const [view,setView]=useState<HubView>("Creator applications");
  const reviewableStreakRequests=streakRequests.filter(request=>request.status!=="Active");
  const counts:Record<HubView,number>={"Creator applications":rows.length,"Apply New Apps":expansionRequests.length,"Streak VIP Code":reviewableStreakRequests.length};
  const activeStatuses:HubStatus[]=view==="Creator applications"
    ?rows.map(row=>applicationStatus(row.status) as HubStatus)
    :view==="Apply New Apps"
      ?expansionRequests.map(request=>request.status as HubStatus)
      :reviewableStreakRequests.map(request=>request.status==="Approved"?"Accepted":request.status==="Declined"?"Declined":"In review");
  const metrics=[
    {label:"Total Applications",value:activeStatuses.length,detail:view,tone:"violet",donut:false},
    {label:"Pending Review",value:activeStatuses.filter(status=>status==="In review").length,detail:"Pending out of total",tone:"amber",donut:true},
    {label:"Accepted",value:activeStatuses.filter(status=>status==="Accepted").length,detail:"Accepted out of total",tone:"mint",donut:true},
    {label:"Declined",value:activeStatuses.filter(status=>status==="Declined").length,detail:"Declined out of total",tone:"coral",donut:true},
  ];
  return <>
    <PageHead title="Applications" copy="Review creator applications, app-access requests, and Streak VIP Code claims in one consistent workspace."/>
    <section className="application-metrics manual-application-metrics application-hub-metrics">{metrics.map(metric=>{const percentage=activeStatuses.length?Math.round(metric.value/activeStatuses.length*100):0;return <article className={`application-metric ${metric.tone} ${metric.donut?"application-metric-with-donut":""}`} key={metric.label}><div><span>{metric.label}</span><strong>{metric.value}</strong><small>{metric.detail}</small></div>{metric.donut?<div className="application-donut" style={{background:`conic-gradient(var(--donut-color) ${percentage}%,#ece5df ${percentage}% 100%)`}} role="img" aria-label={`${metric.label}: ${metric.value} of ${activeStatuses.length}, ${percentage}%`}><span>{percentage}%</span></div>:<b aria-hidden="true"/>}</article>})}</section>
    <div className="segmented application-hub-tabs">{(["Creator applications","Apply New Apps","Streak VIP Code"] as HubView[]).map(item=><button className={view===item?"active":""} onClick={()=>setView(item)} key={item}>{item}<span>{counts[item]}</span></button>)}</div>
    {view==="Streak VIP Code"
      ?<StreakVipReview requests={reviewableStreakRequests} setRequests={setStreakRequests} notify={notify} persist={persist}/>
      :<div className="applications-hub-inner"><Applications key={view} initialView={view} rows={rows} expansionRequests={expansionRequests} setApps={setApps} setExpansionRequests={setExpansionRequests} notify={notify} persist={persist}/></div>}
  </>;
}

function StreakVipReview({requests,setRequests,notify,persist}:{requests:StreakRequest[];setRequests:React.Dispatch<React.SetStateAction<StreakRequest[]>>;notify:(message:string)=>void;persist:(entity:string,item:unknown)=>void}){
  type DisplayStatus="In review"|"Accepted"|"Declined";
  const [filter,setFilter]=useState<DisplayStatus>("In review");
  const [query,setQuery]=useState("");
  const [appFilter,setAppFilter]=useState("All");
  const [sort,setSort]=useState("Newest first");
  const [expanded,setExpanded]=useState<string|null>(null);
  const [editing,setEditing]=useState<StreakRequest|null>(null);
  const [vipCode,setVipCode]=useState("");
  const displayStatus=(request:StreakRequest):DisplayStatus=>request.status==="Approved"?"Accepted":request.status==="Declined"?"Declined":"In review";
  const visible=requests
    .filter(request=>displayStatus(request)===filter&&(request.creator+" "+request.id).toLowerCase().includes(query.toLowerCase())&&(appFilter==="All"||request.selectedApp===appFilter))
    .sort((a,b)=>sort==="Oldest first"?new Date(a.submitted).getTime()-new Date(b.submitted).getTime():sort==="Most completed"?b.completedTasks-a.completedTasks:new Date(b.submitted).getTime()-new Date(a.submitted).getTime());
  const update=(request:StreakRequest,status:"Approved"|"Declined",code="")=>{const updated:StreakRequest={...request,status,vipCode:status==="Approved"?code:"",reviewedAt:new Date().toISOString()};setRequests(items=>items.map(item=>item.id===request.id?updated:item));persist("streakRequest",updated);notify(status==="Approved"?`VIP code accepted and sent to ${request.creator}.`:`Streak VIP Code request from ${request.creator} declined.`)};
  const undo=(request:StreakRequest)=>{const updated:StreakRequest={...request,status:"In review",vipCode:"",reviewedAt:undefined};setRequests(items=>items.map(item=>item.id===request.id?updated:item));persist("streakRequest",updated);notify(`${request.creator}’s Streak VIP Code request moved back to In review.`)};
  const openCode=(request:StreakRequest)=>{setEditing(request);setVipCode(request.vipCode||"")};
  const close=()=>{setEditing(null);setVipCode("")};
  const tabs:DisplayStatus[]=["In review","Accepted","Declined"];
  return <>
    <div className="segmented filters application-status-tabs streak-status-tabs">{tabs.map(item=><button key={item} className={filter===item?"active":""} onClick={()=>setFilter(item)}>{item}<span>{requests.filter(request=>displayStatus(request)===item).length}</span></button>)}</div>
    <section className="panel application-filter-bar streak-vip-filter-bar">
      <label className="application-search"><span>⌕</span><input value={query} onChange={event=>setQuery(event.target.value)} placeholder="Search by creator or request ID…"/></label>
      <label>VIP app<select value={appFilter} onChange={event=>setAppFilter(event.target.value)}><option>All</option><option>Meitu</option><option>BeautyCam</option><option>Wink</option></select></label>
      <label>Sort by<select value={sort} onChange={event=>setSort(event.target.value)}><option>Newest first</option><option>Oldest first</option><option>Most completed</option></select></label>
    </section>
    <section className="panel application-table-card embedded-streak-review">
      {visible.length?<div className="table-wrap"><table className="application-table manual-application-table streak-vip-table"><thead><tr><th>Creator</th><th>Completed Campaigns</th><th>VIP App</th><th>VIP Code</th><th>Submitted</th><th>Actions</th></tr></thead>{visible.map(request=>{const status=displayStatus(request);return <tbody key={request.id}><tr><td data-label="Creator"><div className="creator-cell"><Avatar text={request.creator.split(" ").map(part=>part[0]).slice(0,2).join("")}/><span><b>{request.creator}</b><small>{request.id}</small></span></div></td><td data-label="Completed Campaigns"><div className="submitted-date"><b>{request.completedTasks}/10</b><small>Qualified campaigns</small></div></td><td data-label="VIP App"><ProductBadge product={request.selectedApp}/></td><td data-label="VIP Code">{request.vipCode?<code>{request.vipCode}</code>:<span className="no-social-account">Not assigned</span>}</td><td data-label="Submitted"><div className="submitted-date"><b>{displayDate(request.submitted)}</b><small>{status}</small></div></td><td data-label="Actions"><div className="application-actions streak-vip-actions"><button className="secondary table-action-button" onClick={()=>setExpanded(current=>current===request.id?null:request.id)}>{expanded===request.id?"Close":"View"}</button>{status==="In review"?<><button className="primary table-action-button" onClick={()=>openCode(request)}>Accept</button><button className="danger table-action-button" onClick={()=>update(request,"Declined")}>Decline</button></>:<>{status==="Accepted"&&<button className="secondary table-action-button" onClick={()=>openCode(request)}>Edit</button>}<button className="application-undo-button table-action-button" onClick={()=>undo(request)}>Undo</button></>}</div></td></tr>{expanded===request.id&&<tr className="application-answer-row"><td colSpan={6}><div className="application-answers streak-request-answers"><div className="answers-head"><div><span className="eyebrow">Streak VIP Code · {request.id}</span><h3>{request.creator}</h3></div><small>Submitted {displayDate(request.submitted)}</small></div><div className="answer-grid streak-answer-grid"><article><span>01</span><div><b>Qualified campaign progress</b><p>{request.completedTasks} of 10 campaigns completed.</p></div></article><article><span>02</span><div><b>Selected VIP app</b><p>{request.selectedApp}</p></div></article>{request.vipCode&&<article><span>03</span><div><b>Assigned VIP code</b><p>{request.vipCode}</p></div></article>}</div></div></td></tr>}</tbody>})}</table></div>:<div className="application-empty"><span>★</span><b>No {filter.toLowerCase()} Streak VIP Code requests</b><p>Try another search, app, or status.</p></div>}
    </section>
    {editing&&<div className="modal-layer"><button className="modal-scrim" onClick={close} aria-label="Close VIP code dialog"/><form className="dialog vip-code-dialog" onSubmit={event=>{event.preventDefault();if(!vipCode.trim())return;update(editing,"Approved",vipCode.trim());close()}}><header><div><span className="eyebrow">Streak VIP Code</span><h2>{editing.status==="Approved"?"Edit VIP code":`Accept ${editing.creator}`}</h2><p>{editing.status==="Approved"?`Update the VIP code reflected in ${editing.creator}’s Creator Portal.`:`Provide the one-month ${editing.selectedApp} VIP code before accepting.`}</p></div><button type="button" className="close" onClick={close}>×</button></header><div className="form-body"><div className="vip-recipient"><ProductBadge product={editing.selectedApp}/><span><b>{editing.completedTasks} campaigns completed</b><small>This code becomes visible immediately after acceptance.</small></span></div><label>VIP code<input required autoFocus value={vipCode} onChange={event=>setVipCode(event.target.value)} placeholder="e.g. VIP-MEITU-30D-XXXX"/></label></div><footer><button type="button" className="secondary" onClick={close}>Cancel</button><button className="primary" disabled={!vipCode.trim()}>{editing.status==="Approved"?"Save VIP code":"Accept & send VIP code"}</button></footer></form></div>}
  </>;
}
function Creators({applications,submissions,profiles}:{applications:Application[];submissions:Submission[];profiles:CreatorProfile[]}){
  const [query,setQuery]=useState("");
  const [app,setApp]=useState("All");
  const [socialPlatform,setSocialPlatform]=useState("All");
  const [selectedNiches,setSelectedNiches]=useState<string[]>([]);
  const [followers,setFollowers]=useState("All");
  const [province,setProvince]=useState("All");
  const [city,setCity]=useState("All");
  const [creatorPage,setCreatorPage]=useState(1);
  const [pageSize,setPageSize]=useState(10);
  const fallbacks:Application[]=[
    {id:"CRE-1",name:"Salsa Nabila",handle:"@salsaglow",city:"Kota Jakarta Selatan",province:"DKI Jakarta",category:"Beauty",product:"Meitu",followers:"214K",status:"Accepted",score:98,submitted:"",avatar:"SN",email:"salsa@example.com",whatsapp:"628141234567",interestedApps:"Meitu,BeautyCam,Wink",tiktokFollowers:"100.000 - 250.000 Followers",tiktokUrl:"https://www.tiktok.com/@salsaglow",instagramUrl:"https://www.instagram.com/salsanabila"},
    {id:"CRE-2",name:"Fajar Malik",handle:"@fajarmotion",city:"Kota Bandung",province:"Jawa Barat",category:"Editing / Photography",product:"Wink",followers:"511K",status:"Accepted",score:95,submitted:"",avatar:"FM",email:"fajar@example.com",whatsapp:"628131234567",interestedApps:"Wink",tiktokFollowers:"> 500.000 Followers",tiktokUrl:"https://www.tiktok.com/@fajarmotion"},
    {id:"CRE-3",name:"Gita Ayu",handle:"@gitaglow",city:"Kota Surabaya",province:"Jawa Timur",category:"Beauty",product:"BeautyCam",followers:"74K",status:"Accepted",score:89,submitted:"",avatar:"GA",email:"gita@example.com",whatsapp:"628121234567",interestedApps:"BeautyCam",instagramFollowers:"50.000 - 100.000 Followers",instagramUrl:"https://www.instagram.com/gitglow"},
  ];
  const acceptedHandles=new Set(applications.map(item=>item.handle));
  const source=[...applications,...fallbacks.filter(item=>!acceptedHandles.has(item.handle))];
  const rows=source.map(creator=>{const inferredProvince=creator.province||(creator.city.includes("Jakarta")?"DKI Jakarta":creator.city.includes("Bandung")?"Jawa Barat":creator.city.includes("Surabaya")?"Jawa Timur":creator.city.includes("Yogyakarta")?"DI Yogyakarta":"");const hydrated={...creator,province:inferredProvince};const profile=profiles.find(item=>item.creator===creator.name);return {creator:hydrated,apps:(creator.interestedApps||creator.product).split(","),platforms:[creator.tiktokUrl&&"TikTok",creator.instagramUrl&&"Instagram",creator.threadsUrl&&"Threads"].filter(Boolean) as string[],tier:creator.tiktokFollowers||creator.instagramFollowers||creator.threadsFollowers||creator.followers,tasks:submissions.filter(item=>item.creator===creator.name).length,whatsapp:profile?.whatsapp||creator.whatsapp||""}});
  const niches=[...new Set(rows.flatMap(row=>categoryList(row.creator.category)))];
  const tiers=[...new Set(rows.map(row=>row.tier))];
  const provinces=[...new Set(rows.map(row=>row.creator.province).filter(Boolean) as string[])].sort();
  const cities=[...new Set(rows.filter(row=>province==="All"||row.creator.province===province).map(row=>row.creator.city).filter(Boolean))].sort();
  const visible=rows.filter(row=>{const rowNiches=categoryList(row.creator.category);return ((row.creator.name+" "+row.creator.handle).toLowerCase().includes(query.toLowerCase()))&&(app==="All"||row.apps.includes(app))&&(socialPlatform==="All"||row.platforms.includes(socialPlatform))&&(!selectedNiches.length||selectedNiches.some(item=>rowNiches.includes(item)))&&(followers==="All"||row.tier===followers)&&(province==="All"||row.creator.province===province)&&(city==="All"||row.creator.city===city)});
  const toggleNiche=(item:string)=>setSelectedNiches(current=>current.includes(item)?current.filter(value=>value!==item):[...current,item]);
  useEffect(()=>setCreatorPage(1),[query,app,socialPlatform,selectedNiches,followers,province,city,pageSize]);
  const pageCount=Math.max(1,Math.ceil(visible.length/pageSize));
  const safePage=Math.min(creatorPage,pageCount);
  const firstIndex=(safePage-1)*pageSize;
  const pageRows=visible.slice(firstIndex,firstIndex+pageSize);
  const paginationItems:(number|"ellipsis")[]=pageCount<=7?Array.from({length:pageCount},(_,index)=>index+1):safePage<=4?[1,2,3,4,5,"ellipsis",pageCount]:safePage>=pageCount-3?[1,"ellipsis",pageCount-4,pageCount-3,pageCount-2,pageCount-1,pageCount]:[1,"ellipsis",safePage-1,safePage,safePage+1,"ellipsis",pageCount];
  const exportCreators=()=>{const escape=(value:unknown)=>`"${String(value??"").replaceAll('"','""')}"`;const csv=[["Creator","Handle","Email","WhatsApp","City","Province","Apps","Niches","Campaigns completed"],...visible.map(({creator,apps,tasks,whatsapp})=>[creator.name,creator.handle,creator.email,whatsapp,creator.city,creator.province,apps.join(" · "),categoryList(creator.category).join(" · "),tasks])].map(row=>row.map(escape).join(",")).join("\n");const link=document.createElement("a");const url=URL.createObjectURL(new Blob([csv],{type:"text/csv;charset=utf-8"}));link.href=url;link.download="creator-pool-creators.csv";document.body.append(link);link.click();link.remove();window.setTimeout(()=>URL.revokeObjectURL(url),0)};
  return <>
    <PageHead title="Creators" copy="Search and curate accepted creators by platform, niche, followers, and city."><button type="button" className="secondary" onClick={exportCreators}>Export list</button></PageHead>
    <section className="creator-directory-summary"><div><span>CREATOR DIRECTORY</span><h2>{visible.length} creators in this view</h2><p>Filter the pool, review contact details, and control how many creators appear on each page.</p></div></section>
    <section className="creator-niche-filter panel">
      <header><span>Filter by niche</span><small>Select one or more. Creators matching any selected niche will appear.</small></header>
      <div className="creator-niche-filters">
        <button type="button" aria-pressed={!selectedNiches.length} className={!selectedNiches.length?"active":""} onClick={()=>setSelectedNiches([])}><i>◎</i>All niches</button>
        {niches.map((item,index)=><button type="button" aria-pressed={selectedNiches.includes(item)} className={`${selectedNiches.includes(item)?"active":""} niche-tone-${index%5}`} onClick={()=>toggleNiche(item)} key={item}><i>{categoryIcon(item)}</i>{item}</button>)}
      </div>
    </section>
    <section className="creator-filter-bar creator-filter-bar-compact panel">
      <label><span>Search creators</span><input value={query} onChange={event=>setQuery(event.target.value)} placeholder="Name or username…"/></label>
      <label><span>Social platform</span><select value={socialPlatform} onChange={event=>setSocialPlatform(event.target.value)}><option>All</option>{["Instagram","TikTok","Threads"].map(item=><option key={item}>{item}</option>)}</select></label>
      <label><span>Followers</span><select value={followers} onChange={event=>setFollowers(event.target.value)}><option>All</option>{tiers.map(item=><option key={item}>{item}</option>)}</select></label>
      <label><span>City</span><select value={city} onChange={event=>setCity(event.target.value)}><option>All</option>{cities.map(item=><option key={item}>{item}</option>)}</select></label>
    </section>
    <section className="panel table-panel creator-directory-table">
      <div className="panel-head"><div><h2>{visible.length} creators</h2><p>{visible.length?"Showing "+(firstIndex+1)+"–"+Math.min(firstIndex+pageRows.length,visible.length)+" of "+visible.length:"No creators match these filters"}</p></div></div>
      <div className="table-wrap"><table>
        <thead><tr><th>Creator</th><th>Social Media</th><th>Apps</th><th>Niche</th><th>Contact</th><th>Campaigns completed</th></tr></thead>
        <tbody>{pageRows.map(({creator,apps,tasks,whatsapp})=><tr key={creator.id}>
          <td><div className="creator-cell"><Avatar text={creator.avatar} imageKey={profiles.find(profile=>profile.creator===creator.name)?.avatarKey}/><span><b>{creator.name}</b><small>{[creator.city,creator.province].filter(Boolean).join(", ")}</small></span></div></td>
          <td><SocialAccounts application={creator}/></td>
          <td><div className="product-stack creator-app-stack">{apps.map(product=><ProductBadge key={product} product={product}/>)}</div></td>
          <td><div className="creator-niche-stack">{categoryList(creator.category).map(category=><span className={`creator-niche-pill niche-tone-${kolCategories.indexOf(category)%5}`} key={category}><i>{categoryIcon(category)}</i>{category}</span>)}</div></td>
          <td><div className="application-contact"><a href={"mailto:"+creator.email}>{creator.email||"—"}</a>{whatsapp?<a href={"https://wa.me/"+whatsapp.replace(/\D/g,"")} target="_blank" rel="noreferrer">+{whatsapp} ↗</a>:<small>No WhatsApp</small>}</div></td>
          <td><b>{tasks}</b></td>
        </tr>)}</tbody>
      </table></div>
      <footer className="creator-pagination">
        <button aria-label="Previous page" disabled={safePage===1} onClick={()=>setCreatorPage(page=>Math.max(1,page-1))}>‹</button>
        <div>{paginationItems.map((item,index)=>item==="ellipsis"?<span key={"ellipsis-"+index}>•••</span>:<button key={item} className={safePage===item?"active":""} onClick={()=>setCreatorPage(item)}>{item}</button>)}</div>
        <button aria-label="Next page" disabled={safePage===pageCount} onClick={()=>setCreatorPage(page=>Math.min(pageCount,page+1))}>›</button>
        <label><select value={pageSize} onChange={event=>setPageSize(Number(event.target.value))}><option value={10}>10 / page</option><option value={25}>25 / page</option><option value={50}>50 / page</option><option value={100}>100 / page</option></select></label>
      </footer>
    </section>
  </>
}
function Tasks({creator,rows,creatorCategories,creatorProducts,joinedCampaignIds,onCreate,onPreview,onManage,onJoin,onSubmit}:{creator:boolean;rows:Task[];creatorCategories:string[];creatorProducts:Product[];joinedCampaignIds:string[];onCreate:()=>void;onPreview:(task:Task)=>void;onManage:(task:Task)=>void;onJoin:(task:Task)=>void;onSubmit:(task:Task)=>void}){
  const [productFilter,setProductFilter]=useState<"All"|Product>("All");
  const [statusFilter,setStatusFilter]=useState<"All"|"Ongoing"|"Expired">("All");
  const [searchDraft,setSearchDraft]=useState("");
  const [query,setQuery]=useState("");
  const availableProducts=(creator?creatorProducts:["Meitu","BeautyCam","Wink"] as Product[]).filter((product,index,list)=>list.indexOf(product)===index);
  const profileNiches=creatorCategories.map(normalizedCategory);
  const ranked=rows.filter(task=>!creator||availableProducts.includes(task.product)).map((task,index)=>{const matches=taskNiches(task).filter(niche=>profileNiches.includes(niche));const score=Math.min(99,68+(matches.length*14)+(taskStatusFor(task)==="Ongoing"?4:0)+(task.product==="Meitu"?2:0));return {task,score,index}}).sort((a,b)=>creator?b.score-a.score||a.index-b.index:a.index-b.index);
  const visible=ranked.filter(({task})=>(productFilter==="All"||task.product===productFilter)&&(creator||statusFilter==="All"||taskStatusFor(task)===statusFilter)&&(`${task.title} ${task.id} ${task.product}`.toLowerCase().includes(query.toLowerCase())));
  const collaborationFlow=[
    {icon:"◎",title:"View campaign details",copy:"Review the brief, deadline, and campaign links."},
    {icon:"✦",title:"Create and post",copy:"Create your content and publish it on the selected platform."},
    {icon:"↗",title:"Submit within 7 days after posting",copy:"Send the public post and analytics no later than seven days after it goes live."},
    {icon:"✓",title:"Qualification check",copy:"The Meitu system checks the qualification of your post."},
    {icon:"◇",title:"Complete payment & earn",copy:"If qualified, fill in the payment form and receive your reward."},
  ];
  return <>
    <PageHead title={creator?"Campaigns for you":"Campaigns"} copy={creator?"View and submit campaigns from the apps you are registered in.":"Search, preview, and manage creator campaigns."}>{!creator&&<button className="primary" onClick={onCreate}>＋ Create campaign</button>}</PageHead>
    <form className="panel task-search-bar" onSubmit={event=>{event.preventDefault();setQuery(searchDraft.trim())}}><label><span>⌕</span><input value={searchDraft} onChange={event=>setSearchDraft(event.target.value)} placeholder="Search campaign name or app…" aria-label="Search campaigns"/></label><button className="primary" type="submit">Search</button></form>
    <div className="task-filter-groups">
      <div><span>App</span><div className="segmented task-product-filters">{(["All",...availableProducts] as ("All"|Product)[]).map(product=><button type="button" key={product} className={`${productFilter===product?"active":""} task-filter-${product.toLowerCase()}`} onClick={()=>setProductFilter(product)}>{product==="All"?"All apps":product}<small>{product==="All"?ranked.length:ranked.filter(({task})=>task.product===product).length}</small></button>)}</div></div>
      {!creator&&<div><span>Status</span><div className="segmented task-status-filters">{(["All","Ongoing","Expired"] as const).map(status=><button type="button" key={status} className={statusFilter===status?"active":""} onClick={()=>setStatusFilter(status)}>{status}<small>{status==="All"?ranked.length:ranked.filter(({task})=>taskStatusFor(task)===status).length}</small></button>)}</div></div>}
    </div>
    {creator&&<section className="panel campaign-collaboration-flow"><header><span>CAMPAIGN JOURNEY</span><h2>Campaign Collaboration Flow</h2><p>From campaign details to rewards in five simple steps.</p></header><div>{collaborationFlow.map((step,index)=><article key={step.title}><i aria-hidden="true">{step.icon}</i><span><small>STEP {String(index+1).padStart(2,"0")}</small><b>{step.title}</b><em>{step.copy}</em></span></article>)}</div></section>}
    {creator?<section className="creator-campaign-cards">
      {visible.length?visible.map(({task})=>{const expired=taskStatusFor(task)==="Expired";const joined=joinedCampaignIds.includes(task.id);return <article className={`creator-campaign-card campaign-${task.product.toLowerCase()}`} key={task.id}><div className="creator-campaign-app"><span>App name</span><b>{task.product}</b></div><div className="creator-campaign-title"><span>Campaign name</span><h2>{task.title}</h2></div><p className="creator-campaign-description">{task.brief||"Open the campaign to review the complete creative brief."}</p><dl><div><dt>Deadline</dt><dd>{displayDate(task.deadline)} · 23:59 WIB</dd></div></dl><footer><button className="secondary" onClick={()=>onPreview(task)}>View Campaign</button><button className="creator-campaign-submit" disabled={expired} onClick={()=>joined?onSubmit(task):onJoin(task)}>{joined?"Submit your Post":"Join Campaign"}</button></footer></article>}):<div className="panel task-filter-empty"><span>□</span><b>No matching campaigns</b><p>Try another search, app, or status filter.</p></div>}
    </section>:<section className="creator-campaign-cards team-campaign-cards">
      {visible.length?visible.map(({task})=><article className={`creator-campaign-card team-campaign-card campaign-${task.product.toLowerCase()}`} key={task.id}><div className="creator-campaign-app"><span>App name</span><b>{task.product}</b></div><div className="creator-campaign-title"><span>Campaign name</span><h2>{task.title}</h2></div><dl><div><dt>Deadline</dt><dd>{displayDate(task.deadline)} · 23:59 WIB</dd></div></dl><footer><button className="secondary" onClick={()=>onPreview(task)}>Preview</button><button className="creator-campaign-submit" onClick={()=>onManage(task)}>Manage Campaign</button></footer></article>):<div className="panel task-filter-empty"><span>□</span><b>No matching campaigns</b><p>Try another search, app, or status filter.</p></div>}
    </section>}
  </>
}

function Submissions({creator,rows,tasks,onCreate,onRewards,onQualified,onNotQualified}:{creator:boolean;rows:Submission[];tasks:Task[];onCreate:()=>void;onRewards:()=>void;onQualified:(item:Submission)=>void;onNotQualified:(item:Submission,reason:string)=>void}){
  const [status,setStatus]=useState("In review");const [app,setApp]=useState("All");const [task,setTask]=useState("All");const [platform,setPlatform]=useState("All");const [sort,setSort]=useState("Newest");const [declining,setDeclining]=useState<Submission|null>(null);const [reason,setReason]=useState("");const [notes,setNotes]=useState("");const [selectedSubmissionId,setSelectedSubmissionId]=useState("");
  const base=creator?rows.filter(item=>item.creator===currentCreator):rows.filter(item=>normalizeSubmissionStatus(item.status)!=="Draft");
  const filtered=base.filter(item=>(creator||status==="All"||normalizeSubmissionStatus(item.status)===status)&&(app==="All"||item.product===app)&&(task==="All"||item.task===task)&&(platform==="All"||item.platform===platform)).sort((a,b)=>sort==="Highest viewers"?b.aiViews-a.aiViews:sort==="Highest engagement"?engagementRateFor(b)-engagementRateFor(a):(new Date(b.submittedAt||0).getTime()-new Date(a.submittedAt||0).getTime()));
  const totalViews=filtered.reduce((sum,item)=>sum+item.aiViews,0);const calculatedEngagement=filtered.filter(item=>(item.totalEngagement||0)>0||(item.engagementRate||0)>0);const averageEngagement=calculatedEngagement.length?calculatedEngagement.reduce((sum,item)=>sum+engagementRateFor(item),0)/calculatedEngagement.length:0;
  const statuses=["All","In review","Qualified","Not Qualified"];
  return <><PageHead title={creator?"Kiriman saya":"Submissions"} copy={creator?"Pantau pemeriksaan, hasil, dan alasan keputusan tim.":"Verify screenshots, AI-calculated analytics, reward eligibility, and make the final decision."}>{creator&&<button className="primary" onClick={onCreate}>＋ Buat kiriman</button>}</PageHead>{!creator&&<><div className="segmented submission-status-tabs">{statuses.map(item=><button key={item} className={status===item?"active":""} onClick={()=>setStatus(item)}>{item}<small>{base.filter(row=>item==="All"||normalizeSubmissionStatus(row.status)===item).length}</small></button>)}</div><section className="submission-filter-bar panel"><label>App<select value={app} onChange={e=>setApp(e.target.value)}><option>All</option>{["Meitu","BeautyCam","Wink"].map(item=><option key={item}>{item}</option>)}</select></label><label>Campaign<select value={task} onChange={e=>setTask(e.target.value)}><option>All</option>{tasks.map(item=><option key={item.id}>{item.title}</option>)}</select></label><label>Platform<select value={platform} onChange={e=>setPlatform(e.target.value)}><option>All</option>{[...new Set(rows.map(item=>item.platform))].map(item=><option key={item}>{item}</option>)}</select></label><label>Sort by<select value={sort} onChange={e=>setSort(e.target.value)}><option>Newest</option><option>Highest viewers</option><option>Highest engagement</option></select></label></section><section className="submission-metrics"><article><small>Total posts</small><strong>{filtered.length}</strong><span>Current selection</span></article><article><small>Total viewers</small><strong>{fmtNum(totalViews)}</strong><span>AI-verified views</span></article><article><small>Average engagement</small><strong>{averageEngagement.toFixed(1)}%</strong><span>{calculatedEngagement.length} AI-calculated posts</span></article></section></>}
    {creator?<section className="creator-submission-cards">{filtered.length?filtered.map(item=>{const selected=selectedSubmissionId===item.id;return <article className={`creator-submission-card ${selected?"selected":""}`} key={item.id}><button className="creator-submission-select" onClick={()=>setSelectedSubmissionId(selected?"":item.id)} aria-expanded={selected}><span><small>Campaign</small><strong>{item.task}</strong><em>{item.product} · {item.id}</em></span><Status>{normalizeSubmissionStatus(item.status)}</Status></button>{selected&&<div className="creator-submission-details"><dl><div><dt>Campaign</dt><dd>{item.task}</dd></div><div><dt>Post link</dt><dd>{item.postUrl?<a href={item.postUrl} target="_blank" rel="noreferrer">Open post ↗</a>:"—"}</dd></div><div><dt>Status</dt><dd><Status>{normalizeSubmissionStatus(item.status)}</Status></dd></div></dl>{item.qualificationReason&&<p className="qualification-reason">{item.qualificationReason}</p>}{item.evidenceKey&&<a className="analytics-screenshot-link" href={`/api/uploads?key=${encodeURIComponent(item.evidenceKey)}`} target="_blank" rel="noreferrer">View analytics screenshot ↗</a>}{normalizeSubmissionStatus(item.status)==="Qualified"&&<button className="submission-reward-link" onClick={onRewards}>View Rewards →</button>}</div>}</article>}):<div className="panel task-filter-empty"><span>□</span><b>No submissions yet</b><p>Your submitted posts will appear here.</p></div>}</section>:<section className="panel table-panel"><div className="panel-head"><div><h2>{`${status} submissions`}</h2><p>{filtered.length} posts in this selection</p></div></div><div className="table-wrap"><table className="submission-review-table"><thead><tr><th>Creator</th><th>Campaign / product</th><th>Post</th><th>Analytics</th><th>AI recommendation</th><th>Status</th><th>Decision</th></tr></thead><tbody>{filtered.map(item=>{const mismatch=Math.abs(item.views-item.aiViews)/Math.max(item.views,1)>.05;const late=!submittedWithinSevenDays(item.publishedAt,item.submittedAt);const rate=engagementRateFor(item);const totalEngagement=engagementTotalFor(item);return <tr key={item.id}><td><div className="creator-cell"><Avatar text={item.avatar}/><span><b>{item.creator}</b><small>{item.id}</small></span></div></td><td><b>{item.task}</b><small><ProductBadge product={item.product}/></small></td><td>{item.postUrl?<a href={item.postUrl} target="_blank" rel="noreferrer">Open post ↗</a>:"—"}<small>{item.platform} · Posted {displayDate(item.publishedAt)}</small></td><td><div className="engagement-ai-card"><div><span>AI ENGAGEMENT</span><b>{rate>0?rate.toFixed(2)+"%":"Processing"}</b></div><dl><div><dt>Total engagement</dt><dd>{totalEngagement?totalEngagement.toLocaleString():"—"}</dd></div><div><dt>Verified views</dt><dd>{item.aiViews.toLocaleString()}</dd></div></dl><code>{totalEngagement?totalEngagement.toLocaleString()+" ÷ "+item.aiViews.toLocaleString()+" × 100":"Reading screenshot…"}</code><small>{item.platform} · {item.analyticsStatus||"Pending AI extraction"}</small>{item.evidenceKey?<a className="analytics-screenshot-link" href={`/api/uploads?key=${encodeURIComponent(item.evidenceKey)}`} target="_blank" rel="noreferrer">View analytics screenshot ↗</a>:<span className="analytics-screenshot-missing">No screenshot attached</span>}</div></td><td><span className={`ai-verdict ${item.recommendation==="Qualified"?"qualified":"not-qualified"}`}>✦ {item.recommendation}</span><small>{mismatch?"Analytics mismatch detected":late?"Submitted after 7 days":`${item.confidence}% confidence · screenshot matched`}</small></td><td><Status>{normalizeSubmissionStatus(item.status)}</Status>{item.qualificationReason&&<small className="qualification-reason">{item.qualificationReason}</small>}</td><td>{normalizeSubmissionStatus(item.status)==="In review"?<div className="decision-buttons"><button className="primary table-action-button" onClick={()=>onQualified(item)}>✓ Qualified</button><button className="danger table-action-button" onClick={()=>{setDeclining(item);setReason("");setNotes("")}}>Not Qualified</button></div>:<small>Decision complete</small>}</td></tr>})}</tbody></table></div></section>}
    {declining&&<div className="modal-layer"><button className="modal-scrim" onClick={()=>setDeclining(null)}/><form className="dialog qualification-dialog" onSubmit={event=>{event.preventDefault();const finalReason=reason==="Other"?`Other: ${notes.trim()}`:reason;if(!finalReason||reason==="Other"&&!notes.trim())return;onNotQualified(declining,finalReason);setDeclining(null)}}><header><div><span className="eyebrow">Not Qualified · {declining.id}</span><h2>Add the creator-facing reason</h2><p>This reason will be visible on the creator side.</p></div><button type="button" className="close" onClick={()=>setDeclining(null)}>×</button></header><div className="form-body"><label>Reason<select required value={reason} onChange={e=>setReason(e.target.value)}><option value="">Select a reason</option><option>The post is submitted after seven days</option><option>The system detects abnormality in the post’s analytics</option><option>Other</option></select></label>{reason==="Other"&&<label>Manual notes<textarea required value={notes} onChange={e=>setNotes(e.target.value)} placeholder="Explain specifically why this submission is not qualified…"/></label>}</div><footer><button type="button" className="secondary" onClick={()=>setDeclining(null)}>Cancel</button><button className="danger" disabled={!reason||(reason==="Other"&&!notes.trim())}>Confirm Not Qualified</button></footer></form></div>}</>}

function Rewards({creator,rows,tasks,submissions,paymentForms,update,exportCsv}:{creator:boolean;rows:Reward[];tasks:Task[];submissions:Submission[];paymentForms:PaymentForm[];update:(reward:Reward)=>void;exportCsv:()=>void}){
  const {language}=usePortalLanguage();
  const t=(english:string,indonesian:string)=>language==="en"?english:indonesian;
  const [app,setApp]=useState("All");const [task,setTask]=useState("All");const [paymentFormFilter,setPaymentFormFilter]=useState("All");const [failedReward,setFailedReward]=useState<Reward|null>(null);const [failureReason,setFailureReason]=useState("");const moneyRows=rows.filter(item=>item.amount>0&&(creator?item.creator===currentCreator:true));const visible=moneyRows.filter(item=>(app==="All"||item.product===app)&&(task==="All"||item.task===task)&&(paymentFormFilter==="All"||(paymentFormFilter==="Form Received")===Boolean(item.paymentFormChecked)));const total=visible.reduce((sum,item)=>sum+item.amount,0);const paid=visible.filter(item=>item.status==="Fully Paid").reduce((sum,item)=>sum+item.amount,0);const views=visible.reduce((sum,item)=>sum+item.views,0);const paidCount=visible.filter(item=>item.status==="Fully Paid").length;
  const changeRewardStatus=(item:Reward,status:string)=>{if(status==="Pay Fail"){setFailedReward(item);setFailureReason(item.failureReason||"");return}update({...item,status,paidAt:status==="Fully Paid"?item.paidAt||new Date().toISOString():"",failureReason:""})};
  return <>
    <PageHead title={creator?"Hadiah":"Rewards"} copy={creator?"Isi payment form sesuai aplikasi dan pantau status pembayaranmu.":"Track cash rewards, payment-form readiness, and campaign spend."}>{!creator&&<button className="primary" onClick={exportCsv}>↓ Export paid-ready</button>}</PageHead>
    {creator&&<section className="panel payment-process-note"><span>⌁</span><div><h2>{t("Payment process","Proses pembayaran")}</h2><p>{t("Payments are processed approximately","Pembayaran diproses sekitar")} <b>{t("45 business days after the end of the video release month","45 hari kerja setelah akhir bulan rilis video")}</b>. {t("For example: videos posted in August are recapped on 31 August and paid around 30 September–15 October, excluding Saturdays, Sundays, and public holidays.","Contoh: video yang diposting pada Agustus direkap 31 Agustus dan dibayar sekitar 30 September–15 Oktober, tidak termasuk Sabtu, Minggu, dan hari libur.")}</p><p>{t("All payments are sent from overseas, so processing may take longer.","Semua pembayaran dikirim dari luar negeri, sehingga prosesnya dapat membutuhkan waktu lebih lama.")}</p></div></section>}
    {!creator&&<section className="reward-filter-bar panel"><label>App<select value={app} onChange={e=>setApp(e.target.value)}><option>All</option>{["Meitu","BeautyCam","Wink"].map(item=><option key={item}>{item}</option>)}</select></label><label>Campaign<select value={task} onChange={e=>setTask(e.target.value)}><option>All</option>{tasks.map(item=><option key={item.id}>{item.title}</option>)}</select></label><label>Payment form<select value={paymentFormFilter} onChange={e=>setPaymentFormFilter(e.target.value)}><option>All</option><option>Form Received</option><option>Awaiting Form</option></select></label><p>Payment-form completion and reward status are tracked independently, so changing one will not overwrite the other.</p></section>}
    <section className={`reward-summary ${creator?"creator-reward-summary":""}`}><article><small>Total rewards</small><strong>{fmtIdr(total)}</strong><span>{visible.length} qualified cash rewards</span></article><article><small>Paid</small><strong>{fmtIdr(paid)}</strong><span>{paidCount} payment forms checked</span></article><article className="dark"><small>Qualified viewers</small><strong>{fmtNum(views)}</strong><span>Current app/campaign selection</span></article></section>
    <section className="panel table-panel"><div className="panel-head"><div><h2>{creator?"Riwayat hadiah":"Payment tracker"}</h2><p>{creator?"Isi form pembayaran yang sesuai dengan aplikasi reward-mu.":"Only qualified submissions with money rewards appear here"}</p></div></div><div className="table-wrap"><table className="reward-payment-table"><thead><tr><th>Creator</th><th>Campaign</th><th>App</th><th>Views</th><th>Reward</th><th>Payment form</th><th>Status</th></tr></thead><tbody>{visible.map(item=>{
      const submission=submissions.find(entry=>entry.id===item.submissionId);const postingMonth=submission?.publishedAt?.slice(0,7);const matchingForms=paymentForms.filter(entry=>entry.product===item.product);const form=(postingMonth&&matchingForms.find(entry=>entry.month===postingMonth))||[...matchingForms].sort((a,b)=>b.month.localeCompare(a.month))[0];
      return <tr key={item.id}><td><b>{item.creator}</b><small>{item.submissionId||item.id}</small></td><td>{item.task}</td><td><ProductBadge product={item.product}/></td><td><b>{fmtNum(item.views)}</b></td><td><b>{fmtIdr(item.amount)}</b></td><td>{creator?<>{form?<a className="payment-form-link" href={form.url} target="_blank" rel="noreferrer">Isi payment form ↗</a>:<span>Form belum tersedia</span>}<small>{form?`Periode ${form.month}`:"Hubungi Team Creator Pool"}</small></>:<label className="payment-check"><input type="checkbox" checked={Boolean(item.paymentFormChecked)} onChange={event=>update({...item,paymentFormChecked:event.target.checked?1:0,status:event.target.checked&&item.status==="Please Fill In Payment Form"?"In Payment":item.status})}/><span>{item.paymentFormChecked?"Form received":"Awaiting form"}</span></label>}</td><td>{creator?<Status>{item.status}</Status>:<><select className="reward-status-control" value={item.status} onChange={event=>changeRewardStatus(item,event.target.value)}><option>Please Fill In Payment Form</option><option>In Payment</option><option>Fully Paid</option><option>Pay Fail</option></select>{item.status==="Pay Fail"&&item.failureReason&&<small className="payment-failure-reason">{item.failureReason}</small>}</>}</td></tr>
    })}</tbody></table></div></section>
    {failedReward&&<div className="modal-layer"><button className="modal-scrim" onClick={()=>setFailedReward(null)} aria-label="Close payment failure dialog"/><form className="dialog payment-failure-dialog" onSubmit={event=>{event.preventDefault();if(!failureReason.trim())return;update({...failedReward,status:"Pay Fail",failureReason:failureReason.trim(),paidAt:""});setFailedReward(null)}}><header><div><span className="eyebrow">Payment failed · {failedReward.id}</span><h2>Send the reason to {failedReward.creator}</h2><p>The creator will see this message in their reward details.</p></div><button type="button" className="close" onClick={()=>setFailedReward(null)}>×</button></header><div className="form-body"><label>Failure reason<textarea required autoFocus value={failureReason} onChange={event=>setFailureReason(event.target.value)} placeholder="Explain what failed and what the creator should do next…"/></label></div><footer><button type="button" className="secondary" onClick={()=>setFailedReward(null)}>Cancel</button><button className="danger" disabled={!failureReason.trim()}>Save Pay Fail</button></footer></form></div>}
  </>}

function PaymentForms({forms,setForms,notify,persist,remove}:{forms:PaymentForm[];setForms:React.Dispatch<React.SetStateAction<PaymentForm[]>>;notify:(message:string)=>void;persist:(entity:string,item:unknown)=>void;remove:(entity:string,id:string)=>void}){
  const initialMonth=new Date().toISOString().slice(0,7);
  const urlsFor=(period:string):Record<Product,string>=>({Meitu:forms.find(form=>form.product==="Meitu"&&form.month===period)?.url||"",BeautyCam:forms.find(form=>form.product==="BeautyCam"&&form.month===period)?.url||"",Wink:forms.find(form=>form.product==="Wink"&&form.month===period)?.url||""});
  const [month,setMonth]=useState(initialMonth);
  const [drafts,setDrafts]=useState<Record<Product,string>>(()=>urlsFor(initialMonth));
  const [editingMonth,setEditingMonth]=useState<string|null>(null);
  const [historyMonth,setHistoryMonth]=useState("All");
  const historyMonths=[...new Set(forms.map(form=>form.month))].sort().reverse();
  const historyForms=[...forms].filter(form=>historyMonth==="All"||form.month===historyMonth).sort((a,b)=>b.month.localeCompare(a.month));
  const changeMonth=(period:string)=>{setMonth(period);setDrafts(urlsFor(period));setEditingMonth(forms.some(form=>form.month===period)?period:null)};
  const edit=(form:PaymentForm)=>{setMonth(form.month);setDrafts(urlsFor(form.month));setEditingMonth(form.month);window.setTimeout(()=>document.getElementById("payment-form-editor")?.scrollIntoView({behavior:"smooth",block:"start"}),0)};
  const deleteForm=(form:PaymentForm)=>{if(!window.confirm(`Delete the ${form.product} payment form for ${form.month}?`))return;setForms(items=>items.filter(item=>item.id!==form.id));remove("paymentForm",form.id);if(month===form.month)setDrafts(values=>({...values,[form.product]:""}));notify(`${form.product} payment form for ${form.month} deleted.`)};
  const save=()=>{(["Meitu","BeautyCam","Wink"] as Product[]).forEach(product=>{const form:PaymentForm={id:`PAYFORM-${product}-${month}`,product,month,url:drafts[product],updatedAt:new Date().toISOString()};setForms(items=>items.some(item=>item.id===form.id)?items.map(item=>item.id===form.id?form:item):[form,...items]);persist("paymentForm",form)});setEditingMonth(null);notify(`Payment forms for ${month} saved and visible to eligible creators.`)};
  return <><PageHead title="Payment Forms" copy="Attach one monthly payment form for each app. Eligible creators will see the matching link in Rewards."><button className="primary" onClick={save}>{editingMonth?"Save changes":"Save payment forms"}</button></PageHead><section className="panel payment-form-manager" id="payment-form-editor">{editingMonth&&<div className="payment-editing-note"><span>✎</span><div><b>Editing {editingMonth}</b><small>Update any link below, then save your changes.</small></div><button onClick={()=>changeMonth(initialMonth)}>Cancel edit</button></div>}<div className="payment-month"><label>Payment period<input type="month" value={month} onChange={event=>changeMonth(event.target.value)}/></label><p>Use a new set of links every month. Previous periods remain in the history below.</p></div>{(["Meitu","BeautyCam","Wink"] as Product[]).map(product=><label className="payment-app-form" key={product}><ProductBadge product={product}/><span>Form URL</span><input type="url" value={drafts[product]} onChange={event=>setDrafts(values=>({...values,[product]:event.target.value}))}/>{drafts[product]?<a href={drafts[product]} target="_blank" rel="noreferrer">Test link ↗</a>:<small>No link yet</small>}</label>)}</section><section className="panel table-panel"><div className="panel-head payment-history-head"><div><h2>Payment form history</h2><p>{historyForms.length} of {forms.length} app-period forms</p></div><label>Period<select value={historyMonth} onChange={event=>setHistoryMonth(event.target.value)}><option>All</option>{historyMonths.map(period=><option key={period}>{period}</option>)}</select></label></div><div className="table-wrap"><table><thead><tr><th>Period</th><th>App</th><th>Form link</th><th>Actions</th></tr></thead><tbody>{historyForms.map(form=><tr key={form.id}><td><b>{form.month}</b></td><td><ProductBadge product={form.product}/></td><td>{form.url?<a href={form.url} target="_blank" rel="noreferrer">Open form ↗</a>:<span>Link not set</span>}</td><td><div className="payment-history-actions"><button className="secondary table-action-button" onClick={()=>edit(form)}>Edit</button><button className="danger table-action-button" onClick={()=>deleteForm(form)}>Delete</button></div></td></tr>)}</tbody></table></div></section></>}

function TaskCompletionStreak({requests,setRequests,notify,persist}:{requests:StreakRequest[];setRequests:React.Dispatch<React.SetStateAction<StreakRequest[]>>;notify:(message:string)=>void;persist:(entity:string,item:unknown)=>void}){
  const [filter,setFilter]=useState("In review");const [approving,setApproving]=useState<StreakRequest|null>(null);const [vipCode,setVipCode]=useState("");const visible=requests.filter(request=>filter==="All"||request.status===filter);
  const update=(request:StreakRequest,status:"Approved"|"Declined",code="")=>{const updated={...request,status,vipCode:code,reviewedAt:new Date().toISOString()};setRequests(items=>items.map(item=>item.id===request.id?updated:item));persist("streakRequest",updated);notify(status==="Approved"?`VIP code approved for ${request.creator}.`:`Streak request from ${request.creator} declined.`)};
  return <><PageHead title="Campaign Completion Streak" copy="Approve creators who completed 10 campaigns and issue one free one-month VIP code."/><div className="segmented streak-status-tabs">{["All","In review","Approved","Declined"].map(item=><button key={item} className={filter===item?"active":""} onClick={()=>setFilter(item)}>{item}<small>{requests.filter(request=>item==="All"||request.status===item).length}</small></button>)}</div><section className="panel streak-review-list"><div className="panel-head"><div><h2>{filter} streak requests</h2><p>{visible.length} creators</p></div></div>{visible.length?visible.map(request=><article key={request.id}><Avatar text={request.creator.split(" ").map(part=>part[0]).slice(0,2).join("")}/><div><b>{request.creator}</b><small>{request.id} · Submitted {displayDate(request.submitted)}</small></div><div><small>Completed campaigns</small><strong>{request.completedTasks}/10</strong></div><div><small>VIP app choice</small><ProductBadge product={request.selectedApp}/></div><div>{request.vipCode&&<><small>VIP code</small><code>{request.vipCode}</code></>}</div><Status>{request.status}</Status>{request.status==="In review"&&<div className="row-actions"><button className="decline-action" onClick={()=>update(request,"Declined")}>Decline</button><button className="primary" onClick={()=>{setApproving(request);setVipCode("")}}>Approve &amp; add code</button></div>}{request.status==="Approved"&&<div className="row-actions"><button className="secondary" onClick={()=>{setApproving(request);setVipCode(request.vipCode||"")}}>Edit VIP code</button></div>}</article>):<div className="application-empty"><span>★</span><b>No {filter.toLowerCase()} streak requests</b><p>Eligible creator claims will appear here.</p></div>}</section>{approving&&<div className="modal-layer"><button className="modal-scrim" onClick={()=>setApproving(null)}/><form className="dialog vip-code-dialog" onSubmit={event=>{event.preventDefault();if(!vipCode.trim())return;update(approving,"Approved",vipCode.trim());setApproving(null)}}><header><div><span className="eyebrow">Campaign Completion Streak</span><h2>{approving.status==="Approved"?"Edit VIP code":`Approve ${approving.creator}`}</h2><p>{approving.status==="Approved"?`Correct the code previously sent to ${approving.creator}.`:`Enter the one-month VIP code for ${approving.selectedApp}.`}</p></div><button type="button" className="close" onClick={()=>setApproving(null)}>×</button></header><div className="form-body"><div className="vip-recipient"><ProductBadge product={approving.selectedApp}/><span><b>{approving.completedTasks} campaigns completed</b><small>Reward: VIP gratis 1 bulan</small></span></div><label>VIP code<input required autoFocus value={vipCode} onChange={event=>setVipCode(event.target.value)} placeholder="e.g. VIP-MEITU-30D-XXXX"/></label></div><footer><button type="button" className="secondary" onClick={()=>setApproving(null)}>Cancel</button><button className="primary" disabled={!vipCode.trim()}>{approving.status==="Approved"?"Save corrected code":"Approve & send code"}</button></footer></form></div>}</>}

function Reports({submissions,rewards,tasks}:{submissions:Submission[];rewards:Reward[];tasks:Task[]}){
  const [app,setApp]=useState("All");const [task,setTask]=useState("All");const [month,setMonth]=useState("All");const months=[...new Set(submissions.map(item=>(item.submittedAt||"").slice(0,7)).filter(Boolean))];const rows=submissions.filter(item=>(app==="All"||item.product===app)&&(task==="All"||item.task===task)&&(month==="All"||(item.submittedAt||"").startsWith(month)));const decided=rows.filter(item=>normalizeSubmissionStatus(item.status)!=="In review");const agreed=decided.filter(item=>(normalizeSubmissionStatus(item.status)==="Qualified")===(item.recommendation==="Qualified"));const matchingRewards=rewards.filter(reward=>reward.amount>0&&rows.some(item=>item.id===reward.submissionId));const budget=matchingRewards.reduce((sum,item)=>sum+item.amount,0);const agreement=decided.length?agreed.length/decided.length*100:0;const totalViews=rows.reduce((sum,item)=>sum+item.aiViews,0);
  return <><PageHead title="Reports" copy="Generate performance reports per campaign, app, and month."><button className="primary" onClick={()=>window.print()}>Download report</button></PageHead><section className="report-filter-bar panel"><label>App<select value={app} onChange={e=>setApp(e.target.value)}><option>All</option>{["Meitu","BeautyCam","Wink"].map(item=><option key={item}>{item}</option>)}</select></label><label>Campaign<select value={task} onChange={e=>setTask(e.target.value)}><option>All</option>{tasks.map(item=><option key={item.id}>{item.title}</option>)}</select></label><label>Month<select value={month} onChange={e=>setMonth(e.target.value)}><option>All</option>{months.map(item=><option key={item}>{item}</option>)}</select></label></section><section className="metrics report-metrics"><Metric label="Total posts" value={String(rows.length)} delta="Current selection" icon="↗" tone="coral"/><Metric label="Total views" value={fmtNum(totalViews)} delta="AI-verified" icon="◉" tone="violet"/><Metric label="Budget spent" value={fmtIdr(budget)} delta="Cash rewards" icon="◇" tone="mint"/><Metric label="AI–human agreement" value={`${agreement.toFixed(1)}%`} delta={`${agreed.length} of ${decided.length} decisions`} icon="✓" tone="sky"/></section><section className="panel report-breakdown"><div className="panel-head"><div><h2>Campaign breakdown</h2><p>Posts, viewers, spend, and agreement per campaign</p></div></div><div className="table-wrap"><table><thead><tr><th>Campaign</th><th>App</th><th>Posts</th><th>Views</th><th>Budget spent</th><th>AI–human agreement</th></tr></thead><tbody>{tasks.filter(item=>task==="All"||item.title===task).filter(item=>app==="All"||item.product===app).map(item=>{const taskRows=rows.filter(row=>row.task===item.title);const taskDecided=taskRows.filter(row=>normalizeSubmissionStatus(row.status)!=="In review");const taskAgreed=taskDecided.filter(row=>(normalizeSubmissionStatus(row.status)==="Qualified")===(row.recommendation==="Qualified"));const spend=rewards.filter(reward=>reward.task===item.title&&reward.amount>0&&taskRows.some(row=>row.id===reward.submissionId)).reduce((sum,reward)=>sum+reward.amount,0);return <tr key={item.id}><td><b>{item.title}</b></td><td><ProductBadge product={item.product}/></td><td>{taskRows.length}</td><td>{fmtNum(taskRows.reduce((sum,row)=>sum+row.aiViews,0))}</td><td>{fmtIdr(spend)}</td><td>{taskDecided.length?`${(taskAgreed.length/taskDecided.length*100).toFixed(1)}%`:"—"}</td></tr>})}</tbody></table></div></section></>}

function CreatorHome({navigate,profile,tasks,submissions,rewards,requests,saveRequest}:{navigate:(p:string)=>void;profile:CreatorProfile;tasks:Task[];submissions:Submission[];rewards:Reward[];requests:StreakRequest[];saveRequest:(request:StreakRequest)=>void}){
  const {language}=usePortalLanguage();
  const t=(english:string,indonesian:string)=>language==="en"?english:indonesian;
  const allCreatorSubmissions=submissions.filter(item=>item.creator===currentCreator);
  const creatorSubmissions=allCreatorSubmissions.filter(item=>normalizeSubmissionStatus(item.status)!=="Draft");
  const qualifiedSubmissions=creatorSubmissions.filter(item=>normalizeSubmissionStatus(item.status)==="Qualified");
  const lifetimeQualifiedPosts=qualifiedSubmissions.length;
  const orderedRequests=[...requests].sort((a,b)=>new Date(b.submitted||0).getTime()-new Date(a.submitted||0).getTime());
  const latest=orderedRequests[0];
  const latestRedemption=orderedRequests.find(request=>request.status==="In review"||request.status==="Approved");
  const resetAt=latestRedemption?(latestRedemption.startTaskCount??latestRedemption.completedTasks):0;
  const cycleCompleted=Math.max(0,lifetimeQualifiedPosts-resetAt);
  const eligible=cycleCompleted>=10;
  const [selectedApp,setSelectedApp]=useState<Product>("Meitu");
  const [showVipHistory,setShowVipHistory]=useState(false);
  const [suggestionIndex,setSuggestionIndex]=useState(0);
  const [swipeStartY,setSwipeStartY]=useState<number|null>(null);
  const vipHistory=orderedRequests.filter(request=>request.status==="Approved"&&request.vipCode);
  const claim=()=>saveRequest({id:`STR-${Date.now().toString().slice(-6)}`,creator:currentCreator,completedTasks:Math.min(cycleCompleted,10),selectedApp,status:"In review",submitted:new Date().toISOString(),startTaskCount:lifetimeQualifiedPosts});
  const campaignsSubmitted=new Set(creatorSubmissions.map(item=>item.task)).size;
  const totalViews=creatorSubmissions.reduce((sum,item)=>sum+(item.aiViews||item.views),0);
  const totalEarnings=rewards.filter(item=>item.creator===currentCreator&&item.amount>0).reduce((sum,item)=>sum+item.amount,0);
  const creatorTotals=[...new Set(submissions.map(item=>item.creator))].map(creator=>({creator,views:submissions.filter(item=>item.creator===creator&&normalizeSubmissionStatus(item.status)==="Qualified").reduce((sum,item)=>sum+(item.aiViews||item.views),0)})).sort((a,b)=>b.views-a.views);
  const position=Math.max(1,creatorTotals.findIndex(item=>item.creator===currentCreator)+1);
  const summaryCards=[
    {icon:"▤",tone:"campaigns",label:t("Campaigns submitted","Kampanye yang dikirim"),value:String(campaignsSubmitted),copy:t("Open your submitted campaigns","Buka kampanye yang telah dikirim"),page:"Submissions"},
    {icon:"#",tone:"position",label:t("Position","Posisi"),value:`#${position}`,copy:t("View the creator leaderboard","Lihat papan peringkat kreator"),page:"Leaderboard"},
    {icon:"◉",tone:"views",label:t("Total views","Total tayangan"),value:fmtNum(totalViews),copy:t("Across all submitted posts","Dari semua postingan yang dikirim"),page:"Submissions"},
    {icon:"$",tone:"earnings",label:t("Total earnings","Total pendapatan"),value:fmtIdr(totalEarnings),copy:t("Open your rewards","Buka hadiah Anda"),page:"Rewards"},
  ];
  const socialBrands=[
    {product:"Meitu" as Product,icon:"/canva/meitu-app.png",copy:"Tips editing, campaign terbaru, dan inspirasi kreator.",links:[["TikTok","https://www.tiktok.com/@meitu.id"],["Instagram","https://www.instagram.com/meitu.indonesia/"],["Threads","https://www.threads.com/@meitu.indonesia"]]},
    {product:"BeautyCam" as Product,icon:"/canva/beautycam-app.png",copy:"Portrait inspiration dan tren beauty yang lagi ramai.",links:[["TikTok","https://www.tiktok.com/@beautycam.id.official"],["Instagram","https://www.instagram.com/beautycam.indonesia/"],["Threads","https://www.threads.com/@beautycam.indonesia"]]},
    {product:"Wink" as Product,icon:"/canva/wink-app.png",copy:"Tutorial video, transitions, dan creator spotlights.",links:[["TikTok","https://www.tiktok.com/@winkofficial.id"],["Instagram","https://www.instagram.com/winkapp.id/"],["Threads","https://www.threads.com/@winkapp.id"]]},
  ];
  const profileComplete=Boolean(profile.displayName?.trim()&&profile.contactEmail?.trim()&&profile.whatsapp?.trim()&&profile.niches?.trim()&&(profile.tiktokUrl?.trim()||profile.instagramUrl?.trim()||profile.threadsUrl?.trim()));
  const draftSubmission=allCreatorSubmissions.find(item=>normalizeSubmissionStatus(item.status)==="Draft");
  const unsubmittedTasks=tasks.filter(task=>taskStatusFor(task)==="Ongoing"&&!creatorSubmissions.some(item=>item.task===task.title));
  const paymentNeeded=rewards.filter(item=>item.creator===currentCreator&&item.amount>0&&!item.paymentFormChecked&&item.status!=="Fully Paid");
  const suggestions=[
    ...(!profileComplete?[{key:"complete-profile",icon:"○",tone:"coral",title:t("Complete your creator profile","Lengkapi profil kreator Anda"),meta:t("Add your contact details, niches, and at least one social link","Tambahkan kontak, niche, dan minimal satu tautan sosial"),action:t("Complete profile →","Lengkapi profil →"),page:"Profile"}]:[]),
    ...(draftSubmission?[{key:`draft-${draftSubmission.id}`,icon:"✎",tone:"violet",title:t(`Finish your ${draftSubmission.task} draft`,`Selesaikan draf ${draftSubmission.task}`),meta:t("A saved draft is waiting for its post details","Draf tersimpan menunggu detail postingan"),action:t("Open submissions →","Buka kiriman →"),page:"Submissions"}]:[]),
    ...unsubmittedTasks.map(task=>({key:`campaign-${task.id}`,icon:"↗",tone:task.product==="Meitu"?"coral":task.product==="BeautyCam"?"mint":"violet",title:t(`Submit ${task.title}`,`Kirim ${task.title}`),meta:t(`${task.product} · Deadline ${displayDate(task.deadline)}`,`${task.product} · Tenggat ${displayDate(task.deadline)}`),action:t("Open campaign →","Buka kampanye →"),page:"Campaigns"})),
    ...paymentNeeded.map(reward=>({key:`payment-${reward.id}`,icon:"$",tone:"mint",title:t(`Complete payment details for ${reward.task}`,`Lengkapi detail pembayaran untuk ${reward.task}`),meta:t(`${reward.product} · ${fmtIdr(reward.amount)} reward`,`Hadiah ${reward.product} · ${fmtIdr(reward.amount)}`),action:t("Open rewards →","Buka hadiah →"),page:"Rewards"})),
  ];
  if(!suggestions.length)suggestions.push({key:"all-caught-up",icon:"✓",tone:"mint",title:t("You’re all caught up","Semua langkah sudah selesai"),meta:t("No unfinished creator actions right now","Tidak ada tindakan kreator yang belum selesai"),action:t("Browse campaigns →","Lihat kampanye →"),page:"Campaigns"});
  const suggestionSignature=suggestions.map(suggestion=>suggestion.key).join("|");
  const activeSuggestionIndex=Math.min(suggestionIndex,suggestions.length-1);
  useEffect(()=>setSuggestionIndex(0),[suggestionSignature]);
  const changeSuggestion=(direction:number)=>setSuggestionIndex(current=>(current+direction+suggestions.length)%suggestions.length);
  const finishSuggestionSwipe=(clientY:number)=>{if(swipeStartY===null)return;const distance=clientY-swipeStartY;if(distance<-36)changeSuggestion(1);else if(distance>36)changeSuggestion(-1);setSwipeStartY(null)};
  return <>
    <PageHead eyebrow="Ruang kreator" title="Hai, Salsa! 👋" copy="Kamu punya 2 campaign aktif dan 1 kiriman menunggu pemeriksaan."><button className="primary" onClick={()=>navigate("Campaigns")}>Cari campaign baru</button></PageHead>

    <section className="creator-home-stats panel" aria-label={t("Creator performance summary","Ringkasan performa kreator")}>{summaryCards.map(card=><button type="button" key={card.label} onClick={()=>navigate(card.page)}><i className={`home-stat-icon home-stat-icon-${card.tone}`} aria-hidden="true"><span>{card.icon}</span></i><span><small>{card.label}</small><strong>{card.value}</strong><em>{card.copy}</em></span><b aria-hidden="true">↗</b></button>)}</section>

    <div className="creator-columns creator-home-focus">
      <section className="panel suggestion-deck">
        <div className="suggestion-heading">
          <div><span className="eyebrow">NEXT STEPS</span><h2>Next steps</h2><p>Your priorities today</p></div>
          <div className="suggestion-controls"><button type="button" onClick={()=>changeSuggestion(-1)} aria-label="Previous suggestion">↓</button><button type="button" onClick={()=>changeSuggestion(1)} aria-label="Next suggestion">↑</button></div>
        </div>
        <div className="suggestion-counter"><span>{t("Suggestion","Saran")}</span><strong>{activeSuggestionIndex+1}/{suggestions.length}</strong></div>
        <div className="suggestion-stack" role="region" aria-roledescription="carousel" aria-label="Next-step suggestions" tabIndex={0} onKeyDown={event=>{if(event.key==="ArrowUp"){event.preventDefault();changeSuggestion(1)}if(event.key==="ArrowDown"){event.preventDefault();changeSuggestion(-1)}}} onPointerDown={event=>{if(event.target instanceof Element&&event.target.closest("button"))return;setSwipeStartY(event.clientY);event.currentTarget.setPointerCapture(event.pointerId)}} onPointerUp={event=>finishSuggestionSwipe(event.clientY)} onPointerCancel={()=>setSwipeStartY(null)}>
          {suggestions.map((suggestion,index)=>{const distance=(index-activeSuggestionIndex+suggestions.length)%suggestions.length;const position=distance===0?"active":distance===1?"next":"last";const text=`${suggestion.title} ${suggestion.meta}`.toLowerCase();const appTone=text.includes("beautycam")?"suggestion-app-beautycam":text.includes("wink")?"suggestion-app-wink":text.includes("meitu")?"suggestion-app-meitu":"";return <article className={`suggestion-card suggestion-${suggestion.tone} ${appTone} ${position}`} aria-hidden={position!=="active"} key={suggestion.key}><div className="suggestion-card-top"><span><b>{suggestion.icon}</b><em>{t("PRIORITY","PRIORITAS")}</em>{String(index+1).padStart(2,"0")}</span><small>{suggestion.meta}</small></div><div><h3>{suggestion.title}</h3><p>{suggestion.meta}</p></div><button type="button" tabIndex={position==="active"?0:-1} onClick={()=>navigate(suggestion.page)}>{suggestion.action}</button></article>})}
        </div>
        <div className="suggestion-dots" aria-label="Choose suggestion">{suggestions.map((suggestion,index)=><button type="button" className={index===activeSuggestionIndex?"active":""} aria-label={`Show suggestion ${index+1}`} aria-current={index===activeSuggestionIndex?"true":undefined} onClick={()=>setSuggestionIndex(index)} key={suggestion.key}/>)}</div>
        <p className="suggestion-gesture"><span>↑</span> Swipe up for next suggestion</p>
      </section>

      <section className="panel streak task-completion-streak">
        <div className="streak-heading"><div><span>CAMPAIGN GOAL</span><h2>Campaign Completion Streak</h2></div><strong>{Math.min(cycleCompleted,10)}/10</strong></div>
        <p>{eligible?t("Congratulations! You received a free one-month VIP code for one app of your choice.","Selamat! Anda mendapatkan kode VIP gratis selama satu bulan untuk satu aplikasi pilihan."):t(`Complete ${Math.max(0,10-cycleCompleted)} more campaigns to receive a free one-month VIP code.`,`Selesaikan ${Math.max(0,10-cycleCompleted)} kampanye lagi untuk mendapatkan kode VIP gratis selama satu bulan.`)}</p>
        <div className="streak-journey" aria-label={`${Math.min(cycleCompleted,10)} of 10 campaigns completed`}>
          <div className="streak-track"><i style={{width:`${Math.min(cycleCompleted/10*100,100)}%`}}/><b aria-hidden="true" style={{left:`${Math.max(5,Math.min(92,cycleCompleted/10*100))}%`}}/><span aria-hidden="true">⚑</span></div>
          <div className="streak-labels"><small>{Math.min(cycleCompleted,10)} {t("completed","selesai")}</small><small>{t("Goal: free 1-month VIP","Target: VIP gratis 1 bulan")}</small></div>
        </div>
        {eligible&&latest?.status!=="In review"&&<><label>Pilih app<select value={selectedApp} onChange={event=>setSelectedApp(event.target.value as Product)}><option>Meitu</option><option>BeautyCam</option><option>Wink</option></select></label><button className="primary" onClick={claim}>Klaim VIP 1 bulan</button></>}
        {latest&&(latest.status==="In review"||latest.status==="Approved"||latest.status==="Declined")&&<div className="streak-result"><Status>{latest.status}</Status><ProductBadge product={latest.selectedApp}/>{latest.status==="In review"&&<small>VIP request sedang ditinjau. Streak baru sudah dimulai.</small>}{latest.status==="Approved"&&latest.vipCode&&<><small>VIP code kamu</small><code>{latest.vipCode}</code></>}{latest.status==="Declined"&&<small>Kamu dapat memilih app dan mengirim klaim lagi setelah mencapai target.</small>}</div>}
        <button className="secondary vip-history-button" onClick={()=>setShowVipHistory(true)}>VIP Code History <span>{vipHistory.length}</span></button>
      </section>
    </div>

    <section className="creator-social-cta">
      <div className="social-cta-intro"><span>STAY INSPIRED</span><h2>Follow us on social media</h2><p>Ikuti akun resmi Meitu, BeautyCam, dan Wink untuk tren terbaru, tutorial, dan inspirasi konten berikutnya.</p></div>
      <div className="social-brand-grid">{socialBrands.map(brand=><article className={`social-brand-card social-${brand.product.toLowerCase()}`} key={brand.product}><div className="social-brand-heading"><img src={brand.icon} alt=""/><div><small>OFFICIAL ACCOUNT</small><h3>{brand.product}</h3></div></div><div className="social-icon-row">{brand.links.map(([label,url])=><a key={label} href={url} target="_blank" rel="noreferrer" aria-label={`Open ${brand.product} ${label} profile`} title={label}><img src={"/social/"+label.toLowerCase()+".png"} alt=""/></a>)}</div></article>)}</div>
    </section>

    {showVipHistory&&<div className="modal-layer"><button className="modal-scrim" onClick={()=>setShowVipHistory(false)} aria-label="Tutup VIP Code History"/><section className="dialog vip-history-dialog"><header><div><span className="eyebrow">Campaign Completion Streak</span><h2>VIP Code History</h2><p>Daftar VIP Code gratis yang sebelumnya sudah kamu terima.</p></div><button className="close" onClick={()=>setShowVipHistory(false)}>×</button></header><div className="vip-history-list">{vipHistory.length?vipHistory.map(request=><article key={request.id}><ProductBadge product={request.selectedApp}/><div><b>{request.vipCode}</b><small>Diterima {displayDate(request.reviewedAt||request.submitted)} · VIP 1 bulan</small></div><Status>Approved</Status></article>):<div className="application-empty"><span>★</span><b>Belum ada VIP Code</b><p>VIP Code yang sudah disetujui akan tersimpan di sini.</p></div>}</div><footer><button className="primary" onClick={()=>setShowVipHistory(false)}>Selesai</button></footer></section></div>}
  </>}

function Leaderboard({profiles,tasks,submissions,applications,expansionRequests,rewards}:{profiles:CreatorProfile[];tasks:Task[];submissions:Submission[];applications:Application[];expansionRequests:AppExpansionRequest[];rewards:Reward[]}){
  const profileImage=(_name:string)=>undefined;
  const [view,setView]=useState<"Top Monthly Viewers"|"Top Gainers">("Top Monthly Viewers");
  const [appFilter,setAppFilter]=useState<"All"|Product>("All");
  const [taskId,setTaskId]=useState("All");
  const fallbackApps:Record<string,Product[]>={"Salsa Nabila":["Meitu","BeautyCam","Wink"],"Fajar Malik":["Wink"],"Nadia Prameswari":["Meitu","BeautyCam"],"Gita Ayu":["BeautyCam"]};
  const appsFor=(name:string)=>{const application=applications.find(item=>item.name===name);const registered=(application?.interestedApps?.split(",").filter(Boolean)||[]) as Product[];const base=registered.length?registered:application?[application.product]:fallbackApps[name]||[];const requested=expansionRequests.filter(item=>item.creator===name&&item.status==="Accepted").flatMap(item=>item.requestedApps.split(",").filter(Boolean) as Product[]);return [...new Set([...base,...requested])]};
  const creatorNames=[...new Set([...leaderboard.map(person=>person.name),...applications.map(item=>item.name),...submissions.map(item=>item.creator),...rewards.map(item=>item.creator)])];
  const identity=(name:string)=>{const person=leaderboard.find(item=>item.name===name);const application=applications.find(item=>item.name===name);return {name,handle:application?.handle||person?.handle||"@creator",initials:person?.initials||name.split(" ").map(part=>part[0]).slice(0,2).join("")}};
  const months=[...new Set(submissions.map(item=>(item.submittedAt||item.publishedAt||"").slice(0,7)).filter(Boolean))].sort().reverse();
  const monthlyPeriod=months[0]||new Date().toISOString().slice(0,7);
  const availableTasks=tasks.filter(task=>appFilter==="All"||task.product===appFilter);
  const selectedTask=tasks.find(task=>task.id===taskId);
  const monthlyPosts=submissions.filter(item=>(item.submittedAt||item.publishedAt||"").slice(0,7)===monthlyPeriod&&normalizeSubmissionStatus(item.status)==="Qualified"&&(appFilter==="All"||item.product===appFilter)&&(!selectedTask||item.task===selectedTask.title));
  const monthlyRows=creatorNames.map(name=>{const posts=monthlyPosts.filter(item=>item.creator===name);const viewsValue=posts.reduce((sum,item)=>sum+item.views,0);return {...identity(name),posts,viewsValue}}).filter(item=>item.posts.length>0).sort((a,b)=>b.viewsValue-a.viewsValue).slice(0,5).map((item,index)=>({...item,rank:index+1}));
  const gainerRows=creatorNames.map(name=>{const creatorRewards=rewards.filter(item=>item.creator===name&&item.amount>0&&item.status!=="On Hold");const amount=creatorRewards.reduce((sum,item)=>sum+item.amount,0);const posts=submissions.filter(item=>item.creator===name&&item.postUrl);return {...identity(name),amount,rewardCount:creatorRewards.length,posts}}).filter(item=>item.amount>0).sort((a,b)=>b.amount-a.amount).slice(0,5).map((item,index)=>({...item,rank:index+1}));
  const podiumRows=view==="Top Monthly Viewers"?monthlyRows.slice(0,3):gainerRows.slice(0,3);
  const eligibleCount=selectedTask?creatorNames.filter(name=>appsFor(name).includes(selectedTask.product)).length:0;
  const submittedCount=selectedTask?new Set(submissions.filter(item=>item.task===selectedTask.title&&normalizeSubmissionStatus(item.status)!=="Draft").map(item=>item.creator)).size:0;
  const postsFor=(posts:Submission[])=>posts.length?<div className="leaderboard-winner-posts">{posts.slice(0,3).map(post=>post.postUrl?<a href={post.postUrl} target="_blank" rel="noreferrer" key={post.id}>{post.platform} · {post.task} ↗</a>:<span key={post.id}>{post.platform} post unavailable</span>)}</div>:<span className="leaderboard-post-unavailable">No public post link</span>;
  return <><PageHead title="Leaderboard" copy={view==="Top Monthly Viewers"?`Top five creators for ${monthlyPeriod}, ranked by qualified views. Open their winning posts for inspiration.`:"All-time leaders ranked by the total cash rewards they have earned."}><div className="segmented leaderboard-view-tabs">{(["Top Monthly Viewers","Top Gainers"] as const).map(item=><button key={item} className={view===item?"active":""} onClick={()=>setView(item)}>{item}</button>)}</div></PageHead>{view==="Top Monthly Viewers"&&<section className="panel monthly-leaderboard-filter"><label>Filter by app<select value={appFilter} onChange={event=>{setAppFilter(event.target.value as "All"|Product);setTaskId("All")}}><option value="All">All apps</option><option>Meitu</option><option>BeautyCam</option><option>Wink</option></select></label><label>Filter by campaign<select value={taskId} onChange={event=>setTaskId(event.target.value)}><option value="All">All campaigns</option>{availableTasks.map(task=><option key={task.id} value={task.id}>{task.title} · {task.product}</option>)}</select></label><div className="leaderboard-filter-period"><span>Monthly period</span><b>{monthlyPeriod}</b></div>{selectedTask&&<div className="leaderboard-selection-summary"><ProductBadge product={selectedTask.product}/><span><b>{eligibleCount} eligible creators</b><small>{submittedCount} creators submitted for this campaign</small></span></div>}</section>}<section className="creator-leaderboard-podium" aria-label="Top three creators"><header><span>{view==="Top Monthly Viewers"?"Monthly leaders":"All-time gainers"}</span><h2>Top creators</h2></header><div>{podiumRows.map(row=><article className={`podium-rank-${row.rank}`} key={row.name}><b>#{row.rank}</b><Avatar text={row.initials} imageKey={profileImage(row.name)}/><strong>{row.name}</strong><small>{row.handle}</small><em>{"viewsValue" in row?fmtNum(row.viewsValue):fmtIdr(row.amount)}</em></article>)}</div></section><section className="panel leaderboard-top-five"><div className="leaderboard-top-five-head"><span>Rank &amp; creator</span><span>{view==="Top Monthly Viewers"?"Qualified performance":"All-time rewards"}</span><span>Winning posts</span></div>{view==="Top Monthly Viewers"?(monthlyRows.length?monthlyRows.map(row=><article className={row.name===currentCreator?"current-creator":""} key={row.name}><b className="leaderboard-rank">{row.rank===1?"♛":"#"+row.rank}</b><Avatar text={row.initials} imageKey={profileImage(row.name)}/><span className="leaderboard-creator"><strong>{row.name}</strong><small>{row.handle}</small></span><span className="leaderboard-result"><strong>{fmtNum(row.viewsValue)}</strong><small>{row.posts.length} qualified {row.posts.length===1?"post":"posts"}</small></span>{postsFor(row.posts)}</article>):<div className="leaderboard-empty"><span>□</span><h2>No qualified posts found</h2><p>Try a different app or campaign filter.</p></div>):(gainerRows.length?gainerRows.map(row=><article className={row.name===currentCreator?"current-creator":""} key={row.name}><b className="leaderboard-rank">{row.rank===1?"♛":"#"+row.rank}</b><Avatar text={row.initials} imageKey={profileImage(row.name)}/><span className="leaderboard-creator"><strong>{row.name}</strong><small>{row.handle}</small></span><span className="leaderboard-result"><strong>{fmtIdr(row.amount)}</strong><small>{row.rewardCount} all-time reward {row.rewardCount===1?"entry":"entries"}</small></span>{postsFor(row.posts)}</article>):<div className="leaderboard-empty"><span>◇</span><h2>No reward history yet</h2><p>Approved creator rewards will appear here.</p></div>)}</section></>}

function Profile({profile,save}:{profile:CreatorProfile;save:(profile:CreatorProfile)=>Promise<void>}){
  const existingWhatsapp=splitWhatsApp(profile?.whatsapp);
  const [displayName,setDisplayName]=useState(profile?.displayName||profile?.creator||currentCreator);
  const [contactEmail,setContactEmail]=useState(profile?.contactEmail||"salsa@example.com");
  const [selectedPlatforms,setSelectedPlatforms]=useState<Array<"TikTok"|"Instagram"|"Threads">>([profile?.tiktokUrl&&"TikTok",profile?.instagramUrl&&"Instagram",profile?.threadsUrl&&"Threads"].filter(Boolean) as Array<"TikTok"|"Instagram"|"Threads">);
  const [socialLinks,setSocialLinks]=useState({TikTok:profile?.tiktokUrl||"",Instagram:profile?.instagramUrl||"",Threads:profile?.threadsUrl||""});
  const [niches,setNiches]=useState<string[]>(categoryList(profile?.niches||"Beauty"));
  const [whatsappCountryCode,setWhatsappCountryCode]=useState(existingWhatsapp.countryCode);
  const [whatsapp,setWhatsapp]=useState(existingWhatsapp.localNumber);
  const [saving,setSaving]=useState(false);
  const [error,setError]=useState("");
  const togglePlatform=(platform:"TikTok"|"Instagram"|"Threads")=>{setSelectedPlatforms(items=>items.includes(platform)?items.filter(item=>item!==platform):[...items,platform]);setError("")};
  const toggleNiche=(niche:string)=>{setNiches(items=>items.includes(niche)?items.filter(item=>item!==niche):items.length<3?[...items,niche]:items);setError("")};
  const platformDetails=[["TikTok","https://www.tiktok.com/@username"],["Instagram","https://www.instagram.com/username"],["Threads","https://www.threads.net/@username"]] as const;
  return <><PageHead title="Creator profile" copy="Manage your contact details, public social links, and campaign matching preferences."/><form className="creator-profile-editor" onSubmit={async event=>{event.preventDefault();const localNumber=whatsapp.replace(/\D/g,"").replace(/^0+/,"");if(!displayName.trim()){setError("Display name is required.");return}if(!/^\S+@\S+\.\S+$/.test(contactEmail.trim())){setError("Enter a valid contact email.");return}if(!selectedPlatforms.length){setError("Select at least one social platform.");return}const invalidPlatform=selectedPlatforms.find(platform=>{try{const url=new URL(socialLinks[platform]);return !["http:","https:"].includes(url.protocol)}catch{return true}});if(invalidPlatform){setError(`Add a valid public URL for ${invalidPlatform}.`);return}if(!niches.length){setError("Select at least one niche.");return}if(localNumber.length<7||localNumber.length>13){setError("Enter a 7–13 digit WhatsApp number without a leading zero.");return}setSaving(true);setError("");try{await save({...profile,id:profile?.id||"PROFILE-salsa-nabila",creator:currentCreator,displayName:displayName.trim(),contactEmail:contactEmail.trim(),niches:niches.join(","),avatarKey:"",avatarName:"",tiktokUrl:selectedPlatforms.includes("TikTok")?socialLinks.TikTok:"",instagramUrl:selectedPlatforms.includes("Instagram")?socialLinks.Instagram:"",threadsUrl:selectedPlatforms.includes("Threads")?socialLinks.Threads:"",whatsapp:normalizeWhatsApp(whatsappCountryCode,localNumber),updatedAt:new Date().toISOString()});setSaving(false)}catch(reason){setError(reason instanceof Error?reason.message:"Profile changes could not be saved.");setSaving(false)}}}>
    <section className="panel profile-identity-editor profile-identity-editor-no-photo"><div><span className="eyebrow">PUBLIC INFORMATION</span><h2>{displayName||currentCreator}</h2><p>Your name and contact email are used across Creator Pool.</p></div><div className="profile-primary-fields"><label>Display name<input required value={displayName} onChange={event=>setDisplayName(event.target.value)} placeholder="Your public name"/></label><label>Contact email<input required type="email" value={contactEmail} onChange={event=>setContactEmail(event.target.value)} placeholder="you@example.com"/></label></div></section>
    <section className="panel profile-social-editor"><header><h2>Social &amp; Channel Links</h2><p>Select one or more platforms. Each selected platform needs a public channel or profile URL.</p></header><div className="profile-social-options">{platformDetails.map(([platform,placeholder])=>{const checked=selectedPlatforms.includes(platform);return <div className={checked?"selected":""} key={platform}><label className="profile-platform-check"><input type="checkbox" checked={checked} onChange={()=>togglePlatform(platform)}/><span>{platform}</span></label>{checked&&<input type="url" required value={socialLinks[platform]} onChange={event=>setSocialLinks(links=>({...links,[platform]:event.target.value}))} placeholder={placeholder}/>}</div>})}</div></section>
    <section className="panel profile-niche-editor"><header><h2>Your niches</h2><p>Choose up to three niches to improve campaign matching.</p></header><div className="settings-niche-grid">{kolCategories.map(niche=><button type="button" key={niche} className={niches.includes(niche)?"selected":""} disabled={!niches.includes(niche)&&niches.length>=3} onClick={()=>toggleNiche(niche)}>{niches.includes(niche)?"✓ ":""}{niche}</button>)}</div><small>{niches.length}/3 niches selected</small></section>
    <section className="panel profile-whatsapp-editor"><div><span>CONTACT</span><h2>WhatsApp number</h2><p>The Team uses this number only for Creator Pool communication.</p></div><label>WhatsApp number<div className="whatsapp-input"><select aria-label="Country code" value={whatsappCountryCode} onChange={event=>setWhatsappCountryCode(event.target.value)}>{whatsappCountryCodes.map(item=><option key={item.label+"-"+item.code} value={item.code}>{item.flag} {item.label} ({item.code})</option>)}</select><input type="tel" inputMode="numeric" required value={whatsapp} onChange={event=>setWhatsapp(event.target.value.replace(/\D/g,"").replace(/^0+/,""))} placeholder="81234567890"/></div><small>Do not include a leading zero.</small></label></section>
    {error&&<p className="form-error profile-editor-error">{error}</p>}<button className="primary profile-editor-save" disabled={saving}>{saving?"Saving…":"Save changes"}</button>
  </form></>
}

function ReviewDrawer({item,close,decide}:{item:Submission;close:()=>void;decide:(s:string)=>void}){return <div className="modal-layer"><button className="modal-scrim" onClick={close} aria-label="Close review"/><aside className="review-drawer"><header><div><span className="eyebrow">{item.id} · Human review required</span><h2>{item.creator}</h2><p>{item.task}</p></div><button className="close" onClick={close}>×</button></header><div className="review-scroll"><div className="review-summary"><ProductBadge product={item.product}/><Status>{item.status}</Status><span>{item.platform}</span><b>{fmtNum(item.aiViews)} verified views</b></div><section className="ai-panel"><div className="ai-title"><span>✦</span><div><strong>AI recommends {item.recommendation.toLowerCase()}</strong><small>Confidence {item.confidence}% · Prompt v1.5</small></div></div><p>{item.recommendation==="Approve"?"The post URL, boostcode, and video analytics evidence are complete and consistent with the submitted performance data.":"The submission is relevant, but one requirement needs human verification before a final decision."}</p><div className="checklist"><span><b>✓</b> Post URL accessible</span><span><b>✓</b> Boostcode provided</span><span><b>✓</b> Video analytics attached</span><span><b>✓</b> View data complete</span></div><small>AI is advisory only. You retain final decision authority.</small></section><section><h3>Bukti screenshot analitik video</h3>{item.evidenceKey?<a className="analytics-evidence" href={`/api/uploads?key=${encodeURIComponent(item.evidenceKey)}`} target="_blank" rel="noreferrer"><img src={`/api/uploads?key=${encodeURIComponent(item.evidenceKey)}`} alt={`Bukti analitik ${item.creator}`}/><span><b>{item.evidenceName||"Screenshot analitik"}</b><small>Buka gambar ukuran penuh ↗</small></span></a>:<div className="analytics-evidence empty"><span><b>Legacy submission</b><small>Belum ada screenshot tersimpan untuk kiriman lama.</small></span></div>}</section><section><h3>Detail posting</h3><dl className="submission-details"><div><dt>Post URL</dt><dd>{item.postUrl?<a href={item.postUrl} target="_blank" rel="noreferrer">Buka postingan ↗</a>:"—"}</dd></div><div><dt>Tanggal publikasi</dt><dd>{item.publishedAt||"—"}</dd></div><div><dt>Boostcode</dt><dd><code>{item.boostCode||"—"}</code></dd></div></dl></section><section><h3>Analytics verification</h3><dl className="analytics"><div><dt>Declared views tier</dt><dd>{item.views.toLocaleString()}</dd></div><div><dt>AI extracted views</dt><dd>{item.aiViews.toLocaleString()}</dd></div><div><dt>Total engagement</dt><dd>{engagementTotalFor(item).toLocaleString()}</dd></div><div><dt>Engagement rate</dt><dd>{engagementRateFor(item).toFixed(2)}%</dd></div></dl><p className="analytics-formula">{engagementTotalFor(item).toLocaleString()} total engagement ÷ {item.aiViews.toLocaleString()} views × 100</p></section><label className="note-label">Internal note<textarea placeholder="Add context for the audit log…"/></label></div><footer><button className="danger" onClick={()=>decide("Revision requested")}>↻ Request revision</button><button className="primary" onClick={()=>decide("Approved")}>✓ Approve submission</button></footer></aside></div>}

function TaskModal({task,close,save}:{task?:Task;close:()=>void;save:(t:Task)=>void}){
  const [product,setProduct]=useState<Task["product"]>(task?.product||"Meitu");
  const [niches,setNiches]=useState<string[]>(task?taskNiches(task):["Beauty"]);
  const [error,setError]=useState("");
  const toggleNiche=(niche:string)=>{setNiches(current=>current.includes(niche)?current.filter(item=>item!==niche):[...current,niche]);setError("")};
  const toggleAllNiches=()=>{setNiches(niches.length===kolCategories.length?[]:[...kolCategories]);setError("")};
  return <div className="modal-layer"><button className="modal-scrim" onClick={close}/><form className="dialog task-dialog" onSubmit={e=>{e.preventDefault();if(!niches.length){setError("Pilih minimal satu niche KOL untuk rekomendasi campaign.");return}const fd=new FormData(e.currentTarget);save({id:task?.id||`TSK-${Date.now().toString().slice(-4)}`,title:String(fd.get("title")),product,platform:task?.platform||"TikTok · Instagram · Threads",startsAt:String(fd.get("startsAt")),deadline:String(fd.get("deadline")),joined:task?.joined||0,budget:0,status:task?.status||"Active",progress:task?.progress||0,cover:product==="Meitu"?"peach":product==="Wink"?"violet":"blue",niches:niches.join(","),brief:String(fd.get("brief")),referenceLink:String(fd.get("referenceLink")),tutorialLink:String(fd.get("tutorialLink"))})}}><header><div><span className="eyebrow">{task?`Manage ${task.id}`:"New campaign"}</span><h2>{task?"Edit campaign":"Create a creator campaign"}</h2><p>Set the brief resources and deadline. Creators may submit repeatedly until the deadline.</p></div><button type="button" className="close" onClick={close}>×</button></header><div className="form-body"><label>Campaign title<input name="title" required defaultValue={task?.title} placeholder="e.g. Eid Portrait Refresh"/></label><label>Product<div className="check-row">{["Meitu","BeautyCam","Wink"].map(p=><button type="button" key={p} className={product===p?"selected":""} onClick={()=>setProduct(p as Task["product"])}>{product===p?"✓ ":""}{p}</button>)}</div></label><label>Creator-facing brief<textarea name="brief" required defaultValue={task?.brief} placeholder="Describe the creative objective and the result creators should show…"/></label><div className="two-col"><label>Reference link<input name="referenceLink" type="url" required defaultValue={task?.referenceLink} placeholder="https://…"/></label><label>How to access feature / tutorial link<input name="tutorialLink" type="url" required defaultValue={task?.tutorialLink} placeholder="https://…"/></label></div><label><span className="task-niche-heading"><span>Brief ini cocok untuk niche KOL apa? <small className="form-help inline">Pilih sebanyak yang dibutuhkan</small></span><button type="button" className="select-all-niches" onClick={toggleAllNiches}>{niches.length===kolCategories.length?"Clear all":"Select all"}</button></span><div className="app-choice-grid category-choice-grid task-niche-grid">{kolCategories.map(niche=><button type="button" key={niche} className={niches.includes(niche)?"selected":""} onClick={()=>toggleNiche(niche)}>{niches.includes(niche)?"✓ ":""}{niche}</button>)}</div></label><div className="two-col"><label>Campaign starts<input name="startsAt" required type="date" defaultValue={task?.startsAt||new Date().toISOString().slice(0,10)}/></label><label>Submission deadline<input name="deadline" required type="date" defaultValue={task?.deadline||"2026-08-28"}/></label></div><div className="submission-rule-note"><b>Reward eligibility rule</b><p>Content must be submitted no later than 7 days after posting. There is no campaign budget cap, and creators may submit consecutively until the campaign deadline.</p></div>{error&&<p className="form-error">{error}</p>}<div className="ai-suggestion"><span>✦</span><div><b>AI campaign matching</b><p>AI compares the campaign niches with each creator profile and ranks the best-fit briefs from top to bottom.</p></div></div></div><footer><button type="button" className="secondary" onClick={close}>Cancel</button><button className="primary" type="submit">{task?"Save changes":"Publish campaign"}</button></footer></form></div>
}

function TaskPreview({creator,task,submissions,close,manage}:{creator:boolean;task:Task;submissions:Submission[];close:()=>void;manage:()=>void}){
  const related=submissions.filter(item=>item.task===task.title&&normalizeSubmissionStatus(item.status)!=="Draft");
  const qualified=related.filter(item=>normalizeSubmissionStatus(item.status)==="Qualified").length;
  const status=taskStatusFor(task);
  return <div className="modal-layer"><button className="modal-scrim" onClick={close}/><section className="dialog task-preview-dialog"><header><div><span className="eyebrow">{creator?`${task.product} campaign`:`Campaign preview · ${task.id}`}</span><h2>{task.title}</h2><p>{creator?"Review the complete campaign information before creating your post.":"Live campaign details and submission performance."}</p></div><button className="close" onClick={close}>×</button></header><div className="task-preview-body">{!creator&&<div className="task-preview-stats"><article><small>Status</small><Status>{status}</Status></article><article><small>Creators submitted</small><strong>{new Set(related.map(item=>item.creator)).size}</strong></article><article><small>Posts submitted</small><strong>{related.length}</strong></article><article><small>Qualified posts</small><strong>{qualified}</strong></article></div>}<dl className={creator?"creator-campaign-preview-grid":""}><div><dt>App</dt><dd><ProductBadge product={task.product}/></dd></div><div><dt>Status</dt><dd><Status>{status}</Status></dd></div>{!creator&&<div><dt>Campaign period</dt><dd>{displayDate(task.startsAt)} – {displayDate(task.deadline)}</dd></div>}<div className="task-preview-deadline"><dt>Submission deadline</dt><dd>{displayDate(task.deadline)} · 23:59 WIB</dd></div><div className="task-preview-brief"><dt>Brief description</dt><dd>{task.brief||"No brief description provided."}</dd></div></dl><div className="task-preview-links">{task.referenceLink&&<a href={task.referenceLink} target="_blank" rel="noreferrer">Open reference link ↗</a>}{task.tutorialLink&&<a href={task.tutorialLink} target="_blank" rel="noreferrer">Open feature tutorial ↗</a>}</div></div><footer><button className="secondary" onClick={close}>Close</button>{!creator&&<button className="primary" onClick={manage}>Manage campaign</button>}</footer></section></div>
}

function ApplyAppsModal({currentApps,requests,close,save}:{currentApps:Product[];requests:AppExpansionRequest[];close:()=>void;save:(request:AppExpansionRequest)=>void}){
  const [selectedApps,setSelectedApps]=useState<Product[]>([]);
  const [reason,setReason]=useState("");
  const [error,setError]=useState("");
  const allProducts:Product[]=["Meitu","BeautyCam","Wink"];
  const pendingApps=requests.filter(request=>request.status==="In review").flatMap(request=>request.requestedApps.split(",") as Product[]);
  const newApps=allProducts.filter(product=>!currentApps.includes(product));
  const selectableApps=newApps.filter(product=>!pendingApps.includes(product));
  const toggle=(product:Product)=>{setSelectedApps(current=>current.includes(product)?current.filter(item=>item!==product):[...current,product]);setError("")};
  return <div className="modal-layer"><button className="modal-scrim" onClick={close}/><form className="dialog apply-apps-dialog" onSubmit={e=>{e.preventDefault();if(!selectedApps.length){setError("Pilih minimal satu aplikasi baru.");return}if(!reason.trim()){setError("Jelaskan alasan kamu ingin bergabung dengan aplikasi tersebut.");return}save({id:`APPX-${Date.now().toString().slice(-6)}`,creator:currentCreator,currentApps:currentApps.join(","),requestedApps:selectedApps.join(","),reason:reason.trim(),status:"In review",submitted:new Date().toISOString()})}}><header><div><span className="eyebrow">Creator access</span><h2>Apply New Apps</h2><p>Ajukan akses ke aplikasi lain untuk mendapatkan campaign yang relevan setelah disetujui.</p></div><button type="button" className="close" onClick={close}>×</button></header><div className="form-body"><section className="current-apps"><small>Aplikasi yang sudah kamu ikuti</small><div>{currentApps.map(product=><ProductBadge key={product} product={product}/>)}</div></section><label>Pilih aplikasi baru<div className="apply-app-options">{newApps.length?newApps.map(product=>{const pending=pendingApps.includes(product);return <button type="button" key={product} disabled={pending} className={selectedApps.includes(product)?"selected":pending?"pending":""} onClick={()=>!pending&&toggle(product)}><ProductBadge product={product}/><span>{pending?"Sedang direview":selectedApps.includes(product)?"✓ Dipilih":"Pilih aplikasi"}</span></button>}):<div className="all-apps-active"><span>✓</span><div><b>Semua aplikasi sudah aktif</b><p>Kamu sudah terdaftar di Meitu, BeautyCam, dan Wink.</p></div></div>}</div></label>{selectableApps.length>0&&<label>Kenapa kamu ingin bergabung?<textarea required value={reason} onChange={e=>{setReason(e.target.value);setError("")}} placeholder="Ceritakan jenis konten dan ide campaign yang ingin kamu buat…"/></label>}{error&&<p className="form-error">{error}</p>}{pendingApps.length>0&&<div className="application-pending-note"><span>◷</span><div><b>Pengajuan sedang ditinjau</b><p>Campaign untuk aplikasi baru akan muncul setelah Tim Creator Pool menyetujui pengajuanmu.</p></div></div>}</div><footer><button type="button" className="secondary" onClick={close}>Batal</button>{selectableApps.length>0&&<button className="primary" type="submit">Kirim pengajuan</button>}</footer></form></div>
}

function SubmissionModal({close,tasks,initialTaskId,save}:{close:()=>void;tasks:Task[];initialTaskId?:string;save:(s:Submission)=>void}){
  const [file,setFile]=useState<File|null>(null);
  const [uploading,setUploading]=useState(false);
  const [error,setError]=useState("");
  const [selectedTaskId,setSelectedTaskId]=useState(tasks.some(item=>item.id===initialTaskId)?initialTaskId||tasks[0]?.id:tasks[0]?.id||"");
  const [totalViews,setTotalViews]=useState(0);
  const [selectedPlatform,setSelectedPlatform]=useState("TikTok");
  const task=tasks.find(item=>item.id===selectedTaskId)||tasks[0];
  const selectedReward=rewardTierForViews(totalViews)||rewardTiers[0];
  const requiresBoostCode=totalViews>=10000&&(selectedPlatform==="TikTok"||selectedPlatform==="Instagram");

  async function submit(form:HTMLFormElement,draft:boolean){
    if(!task)return;
    if(!draft&&!form.reportValidity())return;
    const fd=new FormData(form);
    if(!draft&&!file){setError("Upload a screenshot of the post analytics before sending for verification.");return}
    if(!draft&&requiresBoostCode&&!String(fd.get("boostCode")||"").trim()){setError(`Add the ${selectedPlatform==="TikTok"?"Spark Ads code":"boostcode"} for this post.`);return}
    setUploading(true);setError("");
    try{
      let evidenceKey="";let evidenceName="";
      if(file){const uploadData=new FormData();uploadData.append("file",file);const response=await fetch("/api/uploads",{method:"POST",body:uploadData});const uploaded=await response.json() as {key?:string;name?:string;error?:string};if(!response.ok||!uploaded.key)throw new Error(uploaded.error||"The analytics screenshot could not be uploaded.");evidenceKey=uploaded.key;evidenceName=uploaded.name||file.name}
      const publishedAt=String(fd.get("publishedAt")||"");
      const submittedAt=new Date().toISOString();
      const late=!draft&&!submittedWithinSevenDays(publishedAt,submittedAt);
      const extractedRate=selectedPlatform==="TikTok"?4.8:selectedPlatform==="Instagram"?3.6:2.9;
      const totalEngagement=draft?0:Math.round(totalViews*extractedRate/100);
      const engagementRate=totalViews>0?totalEngagement/totalViews*100:0;
      save({id:`SUB-${Date.now().toString().slice(-6)}`,creator:currentCreator,task:task.title,product:task.product,platform:selectedPlatform,views:totalViews,aiViews:totalViews,recommendation:draft?"Pending":late?"Not Qualified":"Qualified",confidence:draft?0:late?99:82,status:draft?"Draft":"In review",submitted:draft?"Draft saved":"Just now",submittedAt,avatar:"SN",postUrl:String(fd.get("postUrl")||""),publishedAt,boostCode:requiresBoostCode?String(fd.get("boostCode")||""):"",totalEngagement,analyticsStatus:draft?"Draft":"AI extracted",engagementRate,evidenceKey,evidenceName})
    }catch(reason){setError(reason instanceof Error?reason.message:"The submission could not be saved.");setUploading(false)}
  }

  if(!task)return <div className="modal-layer"><button className="modal-scrim" onClick={close}/><section className="dialog empty-submission-dialog"><header><div><span className="eyebrow">Submit your post</span><h2>No ongoing campaigns available</h2><p>You can submit after a campaign for one of your registered apps becomes active.</p></div><button type="button" className="close" onClick={close}>×</button></header><div className="empty-submission-state"><span>□</span><b>Your campaign list is currently closed</b><p>Open Campaigns to review available briefs and deadlines.</p></div><footer><button className="primary" type="button" onClick={close}>Close</button></footer></section></div>;
  return <div className="modal-layer"><button className="modal-scrim" onClick={close}/><form className="dialog submission-dialog" onSubmit={event=>{event.preventDefault();void submit(event.currentTarget,false)}}><header><div><span className="eyebrow">{task.product} · {task.id}</span><h2>Submit your post</h2><p>Complete the post details. The campaign selected from the Campaigns list is preselected for you.</p></div><button type="button" className="close" onClick={close}>×</button></header><div className="task-reward-callout"><span>◇</span><div><small>Selected campaign</small><b>{task.title}</b><p>Submission deadline: {displayDate(task.deadline)} · 23:59 WIB</p></div></div><div className="form-body"><label>Campaign<select required value={task.id} onChange={event=>{setSelectedTaskId(event.target.value);setError("")}}>{tasks.map(option=><option key={option.id} value={option.id}>{option.title} · {option.product}</option>)}</select></label><div className="selected-submission-task"><ProductBadge product={task.product}/><div><b>{task.title}</b><span>{task.id} · Deadline {displayDate(task.deadline)}</span></div><Status>Ongoing</Status></div><div className="two-col"><label>Post platform<select name="platform" value={selectedPlatform} onChange={event=>{setSelectedPlatform(event.target.value);setError("")}}><option>TikTok</option><option>Instagram</option><option>Threads</option></select></label><label>Post link<input name="postUrl" required type="url" placeholder="https://…"/></label></div><div className="two-col"><label>Posting date<input name="publishedAt" required type="date" max={new Date().toISOString().slice(0,10)} defaultValue={new Date().toISOString().slice(0,10)}/></label><label>Total viewers<select name="totalViews" required value={totalViews} onChange={event=>{setTotalViews(Number(event.target.value));setError("")}}>{rewardTiers.map(tier=><option key={tier.views} value={tier.views}>{tier.label}</option>)}</select><small className="form-help">Choose the category shown in your analytics screenshot.</small></label></div><div className="reward-tier-preview"><span>◇</span><div><small>{selectedReward.label}</small><b>{selectedReward.reward}</b><p>Your selected viewer category determines the reward tier shown here.</p></div></div><div className="ai-calculation-note"><span>✦</span><div><b>AI analytics verification</b><p>Upload the post analytics screenshot. Meitu’s system will verify its authenticity and use it to calculate the post’s engagement rate.</p></div></div>{requiresBoostCode?<label>{selectedPlatform==="TikTok"?"Spark Ads code":"Boostcode"}<input name="boostCode" required placeholder={`Paste the ${selectedPlatform==="TikTok"?"Spark Ads code":"boostcode"}`}/><small className="form-help">Required for TikTok or Instagram posts with at least 10.000 views. <a href="https://shorturl.at/L6rlB" target="_blank" rel="noreferrer">How to get a boostcode ↗</a></small></label>:<div className="boost-not-required"><span>✓</span><div><b>No boostcode required</b><p>{selectedPlatform==="Threads"?"Threads posts do not use boostcodes or Spark Ads codes.":"Posts below 10.000 views do not need a boostcode."}</p><a href="https://shorturl.at/L6rlB" target="_blank" rel="noreferrer">Boostcode tutorial ↗</a></div></div>}<label className="upload">Post analytics screenshot<input type="file" accept="image/png,image/jpeg,image/webp" onChange={event=>{setFile(event.target.files?.[0]||null);setError("")}}/><span>↑</span><b>{file?.name||"Choose an analytics screenshot"}</b><small>JPG, PNG, or WEBP · maximum 8 MB</small></label><div className="submission-deadline-warning"><span>!</span><div><b>Submit no later than 7 days after posting</b><p>Submissions received after seven days may be marked Not Qualified. Meitu will verify the authenticity of the analytics before confirming any reward.</p></div></div>{error&&<p className="form-error">{error}</p>}</div><footer><button type="button" className="secondary" disabled={uploading} onClick={event=>{const form=event.currentTarget.form;if(form)void submit(form,true)}}>{uploading?"Saving…":"Save as draft"}</button><button className="primary" type="submit" disabled={uploading}>{uploading?"Uploading analytics…":"Send for verification"}</button></footer></form></div>
}

function EmailSignInModal({close}:{close:()=>void}){
  const [email,setEmail]=useState("");
  const [password,setPassword]=useState("");
  const [showTeamLogin,setShowTeamLogin]=useState(false);
  const [sending,setSending]=useState(false);
  const [error,setError]=useState("");
  async function googleSignIn(){if(!supabase){setError("Supabase configuration is missing. Please contact the Creator Pool team.");return}setSending(true);setError("");const {error:signInError}=await supabase.auth.signInWithOAuth({provider:"google",options:{redirectTo:`${window.location.origin}/auth/callback`}});if(signInError){setSending(false);setError(signInError.message)}}
  async function passwordSignIn(event:React.FormEvent){event.preventDefault();if(!supabase){setError("Supabase configuration is missing. Please contact the Creator Pool team.");return}setSending(true);setError("");const {error:signInError}=await supabase.auth.signInWithPassword({email,password});setSending(false);if(signInError){setError("Email or password is incorrect. Ask the Creator Pool team for a test account.");return}close()}
  return <div className="modal-layer"><button className="modal-scrim" onClick={close} aria-label="Close sign in"/><section className="dialog email-auth-dialog google-auth-dialog"><header><div><span className="eyebrow">CREATORHUB ACCOUNT</span><h2>Continue to CreatorHub</h2><p>Google verifies your identity. The Creator Pool Team still reviews and approves every Creator application.</p></div><button type="button" className="close" onClick={close}>×</button></header><div className="form-body"><button type="button" className="google-signin-button" onClick={googleSignIn} disabled={sending}><span aria-hidden="true">G</span><b>{sending&&!showTeamLogin?"Connecting to Google…":"Continue with Google"}</b></button><div className="google-approval-note"><span>✓</span><p>Signing in does not automatically grant Creator access. New accounts remain <b>In review</b> until approved by the Team.</p></div>{showTeamLogin&&<form className="team-password-form" onSubmit={passwordSignIn}><label>Team email<input required autoFocus type="email" value={email} onChange={event=>setEmail(event.target.value)} placeholder="team@company.com"/></label><label>Password<input required type="password" minLength={6} value={password} onChange={event=>setPassword(event.target.value)} placeholder="Your password"/></label><button className="primary" disabled={sending}>{sending?"Signing in…":"Team sign in"}</button></form>}{error&&<p className="form-error">{error}</p>}<button type="button" className="team-login-toggle" onClick={()=>{setShowTeamLogin(value=>!value);setError("")}}>{showTeamLogin?"Hide Team password login":"Team test account login"}</button></div><footer><button type="button" className="secondary" onClick={close}>Cancel</button></footer></section></div>
}

